using System;
using PX.Data;
using PX.Data.BQL;
using PX.Objects.CS;
using PX.Objects.IN;

namespace Aesthetik.WMS
{
    /// <summary>
    /// DAC extension for INLotSerialStatus.
    /// Surfaces the physical attributes of each roll/piece throughout the inventory lifecycle.
    /// These fields are populated at pre-receiving or physical receiving, and updated
    /// by the CutToOrderEngine when rolls are split.
    /// </summary>
    public sealed class INLotSerialStatusExt : PXCacheExtension<INLotSerialStatus>
    {
        public static bool IsActive() => true;

        #region UsrActualYardage
        /// <summary>
        /// Remaining yardage on this roll. Decremented when a cut is performed.
        /// For cut pieces, this equals the cut amount. For original rolls, this
        /// starts at the mill-reported yardage and decreases with each cut.
        /// </summary>
        [PXDBDecimal(2)]
        [PXDefault(System.TypeCode.Decimal, "0.00")]
        [PXUIField(DisplayName = "Actual Yardage", Enabled = true)]
        public decimal? UsrActualYardage { get; set; }
        public abstract class usrActualYardage : BqlDecimal.Field<usrActualYardage> { }
        #endregion

        #region UsrDyeLot
        /// <summary>
        /// Mill dye lot identifier. Critical for color consistency across multi-roll orders.
        /// Inherited by cut pieces from the source roll.
        /// </summary>
        [PXDBString(30, IsUnicode = true)]
        [PXUIField(DisplayName = "Dye Lot")]
        public string UsrDyeLot { get; set; }
        public abstract class usrDyeLot : BqlString.Field<usrDyeLot> { }
        #endregion

        #region UsrWidth
        /// <summary>
        /// Fabric width in inches. May vary by roll even within the same SKU.
        /// Defaults from the lot/serial class but can be overridden per roll.
        /// </summary>
        [PXDBDecimal(1)]
        [PXUIField(DisplayName = "Width (in)")]
        public decimal? UsrWidth { get; set; }
        public abstract class usrWidth : BqlDecimal.Field<usrWidth> { }
        #endregion

        #region UsrShadeCode
        /// <summary>
        /// Color shade variation (A/B/C). Used for lot matching on multi-roll orders.
        /// Not all rolls have shade codes — depends on the fabric type.
        /// </summary>
        [PXDBString(10, IsUnicode = true)]
        [PXUIField(DisplayName = "Shade Code")]
        public string UsrShadeCode { get; set; }
        public abstract class usrShadeCode : BqlString.Field<usrShadeCode> { }
        #endregion

        #region UsrSourceRoll
        /// <summary>
        /// Parent serial number if this is a cut piece. Null for original rolls.
        /// Creates a permanent traceability link for quality tracking.
        /// Set automatically by CutToOrderEngine; read-only in the UI.
        /// </summary>
        [PXDBString(30, IsUnicode = true)]
        [PXUIField(DisplayName = "Source Roll", Enabled = false)]
        public string UsrSourceRoll { get; set; }
        public abstract class usrSourceRoll : BqlString.Field<usrSourceRoll> { }
        #endregion

        #region UsrDefectFlag
        /// <summary>
        /// Marks this roll as having known defects. Rolls with DefectFlag = true
        /// are excluded from the TextilePickOptimizer's auto-pick candidates
        /// and from CutToOrderEngine cut candidates unless manually overridden.
        /// </summary>
        [PXDBBool]
        [PXDefault(false)]
        [PXUIField(DisplayName = "Defect Flag")]
        public bool? UsrDefectFlag { get; set; }
        public abstract class usrDefectFlag : BqlBool.Field<usrDefectFlag> { }
        #endregion

        #region UsrInventoryStatus
        /// <summary>
        /// Piece goods lifecycle status. Controls which workflows can act on this serial.
        /// Values: IN-TRANSIT, RECEIVING, PUT-AWAY, AVAILABLE, XDOCK-HOLD
        /// </summary>
        [PXDBString(15, IsUnicode = true)]
        [PXDefault(PieceGoodsConstants.InvStatus_Available)]
        [PXUIField(DisplayName = "Piece Status")]
        [PXStringList(
            new[] {
                PieceGoodsConstants.InvStatus_InTransit,
                PieceGoodsConstants.InvStatus_Receiving,
                PieceGoodsConstants.InvStatus_PutAway,
                PieceGoodsConstants.InvStatus_Available,
                PieceGoodsConstants.InvStatus_CrossDockHold
            },
            new[] {
                "In-Transit",
                "Receiving",
                "Put-Away",
                "Available",
                "Cross-Dock Hold"
            })]
        public string UsrInventoryStatus { get; set; }
        public abstract class usrInventoryStatus : BqlString.Field<usrInventoryStatus> { }
        #endregion

        #region UsrPreAssignedBin
        /// <summary>
        /// Target bin assigned before physical arrival. Used by the PreReceivingEngine
        /// for planned put-away and by the CrossDockManager to show the intended
        /// destination on the pick/pack display. Updated if the roll is physically
        /// placed in a different bin.
        /// </summary>
        [PXDBString(30, IsUnicode = true)]
        [PXUIField(DisplayName = "Pre-Assigned Bin")]
        public string UsrPreAssignedBin { get; set; }
        public abstract class usrPreAssignedBin : BqlString.Field<usrPreAssignedBin> { }
        #endregion

        #region UsrContainerNo
        /// <summary>
        /// Shipping container ID linking rolls to the same inbound shipment.
        /// Used for container-level put-away tracking and the cross-dock dashboard.
        /// </summary>
        [PXDBString(30, IsUnicode = true)]
        [PXUIField(DisplayName = "Container #")]
        public string UsrContainerNo { get; set; }
        public abstract class usrContainerNo : BqlString.Field<usrContainerNo> { }
        #endregion
    }
}

using System;
using PX.Data;
using PX.Data.BQL;
using PX.Objects.SO;

namespace Aesthetik.WMS
{
    /// <summary>
    /// SOOrder DAC extension — HubSpot deal ID, WMS status, compliance hold.
    /// Migrated from HeritageFabricsPOv5 during ISV consolidation.
    /// </summary>
    public sealed class SOOrderExt : PXCacheExtension<SOOrder>
    {
        public static bool IsActive() => true;

        #region UsrHubSpotDealId
        public abstract class usrHubSpotDealId : BqlString.Field<usrHubSpotDealId> { }

        [PXDBString(50, IsUnicode = true)]
        [PXUIField(DisplayName = "HubSpot Order ID", Visibility = PXUIVisibility.SelectorVisible)]
        public string UsrHubSpotDealId { get; set; }
        #endregion

        #region UsrWMSStatus
        public abstract class usrWMSStatus : BqlString.Field<usrWMSStatus> { }

        [PXDBString(20, IsUnicode = true)]
        [PXDefault(PersistingCheck = PXPersistingCheck.Nothing)]
        [PXUIField(DisplayName = "WMS Status")]
        [PXStringList(
            new[] { "N", "A", "P", "F", "K", "S" },
            new[] { "Not Started", "Allocated", "Picking", "Finishing", "Packed", "Shipped" }
        )]
        public string UsrWMSStatus { get; set; }
        #endregion

        #region UsrComplianceHold
        public abstract class usrComplianceHold : BqlBool.Field<usrComplianceHold> { }

        [PXDBBool]
        [PXDefault(false, PersistingCheck = PXPersistingCheck.Nothing)]
        [PXUIField(DisplayName = "Compliance Hold", Enabled = false)]
        public bool? UsrComplianceHold { get; set; }
        #endregion

        #region UsrComplianceHoldReason
        public abstract class usrComplianceHoldReason : BqlString.Field<usrComplianceHoldReason> { }

        [PXDBString(500, IsUnicode = true)]
        [PXUIField(DisplayName = "Compliance Hold Reason", Enabled = false)]
        public string UsrComplianceHoldReason { get; set; }
        #endregion
    }
}

using System;
using PX.Data;
using PX.Data.BQL;
using PX.Objects.CS;
using PX.Objects.IN;

namespace Aesthetik.WMS
{
    /// <summary>
    /// DAC extension for INSetup (Inventory Preferences).
    /// Global configuration parameters for the Piece Goods WMS customization.
    /// These values serve as system-wide defaults; some can be overridden
    /// at the lot/serial class level or per-warehouse.
    /// </summary>
    public sealed class INSetupExt : PXCacheExtension<INSetup>
    {
        public static bool IsActive() => true;

        #region General Settings

        #region UsrPGMinRemnant
        /// <summary>
        /// Global minimum remnant threshold in yards. If cutting would leave
        /// a remnant below this value, the CutToOrderEngine suggests shipping
        /// the full roll. Can be overridden per lot/serial class.
        /// </summary>
        [PXDBDecimal(2)]
        [PXDefault(System.TypeCode.Decimal, "1.00")]
        [PXUIField(DisplayName = "Min Remnant Yardage",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public decimal? UsrPGMinRemnant { get; set; }
        public abstract class usrPGMinRemnant : BqlDecimal.Field<usrPGMinRemnant> { }
        #endregion

        #region UsrPGAutoQtyMode
        /// <summary>
        /// Enable auto-quantity mode for PIECEGOODS serial class items.
        /// When true, scanning a serial barcode auto-confirms qty = 1
        /// without requiring a separate quantity entry step.
        /// </summary>
        [PXDBBool]
        [PXDefault(true)]
        [PXUIField(DisplayName = "Auto-Quantity Mode",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public bool? UsrPGAutoQtyMode { get; set; }
        public abstract class usrPGAutoQtyMode : BqlBool.Field<usrPGAutoQtyMode> { }
        #endregion

        #region UsrPGAutoPrint
        /// <summary>
        /// Auto-print roll barcode label on receiving.
        /// Sends GS1-128 label to the configured Keyence-compatible printer.
        /// </summary>
        [PXDBBool]
        [PXDefault(true)]
        [PXUIField(DisplayName = "Auto-Print Label on Receiving",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public bool? UsrPGAutoPrint { get; set; }
        public abstract class usrPGAutoPrint : BqlBool.Field<usrPGAutoPrint> { }
        #endregion

        #region UsrPGCutSuffix
        /// <summary>
        /// Serial number suffix format for cut pieces.
        /// {0} is replaced with the sequential cut number.
        /// Example: parent serial FAB-1024-260301-001 becomes FAB-1024-260301-001-C1
        /// </summary>
        [PXDBString(20, IsUnicode = true)]
        [PXDefault("-C{0}")]
        [PXUIField(DisplayName = "Cut Serial Suffix Format",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public string UsrPGCutSuffix { get; set; }
        public abstract class usrPGCutSuffix : BqlString.Field<usrPGCutSuffix> { }
        #endregion

        #endregion

        #region Pre-Receiving & Cross-Dock

        #region UsrPGPreRecv
        /// <summary>
        /// Enable the pre-receiving workflow globally. When true, serial numbers
        /// and bin assignments can be created from PO/ASN data before goods arrive.
        /// </summary>
        [PXDBBool]
        [PXDefault(true)]
        [PXUIField(DisplayName = "Enable Pre-Receiving",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public bool? UsrPGPreRecv { get; set; }
        public abstract class usrPGPreRecv : BqlBool.Field<usrPGPreRecv> { }
        #endregion

        #region UsrPGCrossDock
        /// <summary>
        /// Enable cross-dock fulfillment globally. When true, rolls in
        /// RECV-DOCK location can be picked before formal put-away.
        /// </summary>
        [PXDBBool]
        [PXDefault(true)]
        [PXUIField(DisplayName = "Enable Cross-Dock Fulfillment",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public bool? UsrPGCrossDock { get; set; }
        public abstract class usrPGCrossDock : BqlBool.Field<usrPGCrossDock> { }
        #endregion

        #region UsrPGXDockAge
        /// <summary>
        /// Days a roll can remain in RECV-DOCK before its put-away priority
        /// is escalated. Prevents staging area overflow. Default: 5 days.
        /// </summary>
        [PXDBInt]
        [PXDefault(5)]
        [PXUIField(DisplayName = "Cross-Dock Age Limit (Days)",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public int? UsrPGXDockAge { get; set; }
        public abstract class usrPGXDockAge : BqlInt.Field<usrPGXDockAge> { }
        #endregion

        #region UsrPGInTransitWt
        /// <summary>
        /// Weight penalty for In-Transit stock in the pick optimizer.
        /// Negative value means on-hand stock is preferred. Default: -20.
        /// Set to 0 to treat in-transit equally with on-hand.
        /// </summary>
        [PXDBInt]
        [PXDefault(-20)]
        [PXUIField(DisplayName = "In-Transit Allocation Weight",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public int? UsrPGInTransitWt { get; set; }
        public abstract class usrPGInTransitWt : BqlInt.Field<usrPGInTransitWt> { }
        #endregion

        #region UsrPGYardageVar
        /// <summary>
        /// Yardage variance threshold for receiving validation.
        /// If actual yardage differs from expected by more than this percentage,
        /// the system flags a variance warning. Default: 0.02 (2%).
        /// </summary>
        [PXDBDecimal(4)]
        [PXDefault(System.TypeCode.Decimal, "0.0200")]
        [PXUIField(DisplayName = "Yardage Variance Threshold (%)",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public decimal? UsrPGYardageVar { get; set; }
        public abstract class usrPGYardageVar : BqlDecimal.Field<usrPGYardageVar> { }
        #endregion

        #endregion

        #region Pick Optimizer Weights

        #region UsrPGWtExact
        /// <summary>Scoring weight for exact yardage match (no cut needed). Default: 50.</summary>
        [PXDBInt]
        [PXDefault(50)]
        [PXUIField(DisplayName = "Weight: Exact Match",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public int? UsrPGWtExact { get; set; }
        public abstract class usrPGWtExact : BqlInt.Field<usrPGWtExact> { }
        #endregion

        #region UsrPGWtRemnant
        /// <summary>Scoring weight for minimizing remnant yardage. Default: 30.</summary>
        [PXDBInt]
        [PXDefault(30)]
        [PXUIField(DisplayName = "Weight: Minimize Remnant",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public int? UsrPGWtRemnant { get; set; }
        public abstract class usrPGWtRemnant : BqlInt.Field<usrPGWtRemnant> { }
        #endregion

        #region UsrPGWtDyeLot
        /// <summary>Scoring weight for dye lot matching on multi-roll orders. Default: 15.</summary>
        [PXDBInt]
        [PXDefault(15)]
        [PXUIField(DisplayName = "Weight: Dye Lot Match",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public int? UsrPGWtDyeLot { get; set; }
        public abstract class usrPGWtDyeLot : BqlInt.Field<usrPGWtDyeLot> { }
        #endregion

        #region UsrPGWtLocation
        /// <summary>Scoring weight for location preference (bin vs RECV-DOCK). Default: 10.</summary>
        [PXDBInt]
        [PXDefault(10)]
        [PXUIField(DisplayName = "Weight: Location Preference",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public int? UsrPGWtLocation { get; set; }
        public abstract class usrPGWtLocation : BqlInt.Field<usrPGWtLocation> { }
        #endregion

        #region UsrPGWtFIFO
        /// <summary>Scoring weight for FIFO aging (tiebreaker). Default: 5.</summary>
        [PXDBInt]
        [PXDefault(5)]
        [PXUIField(DisplayName = "Weight: FIFO Age",
            FieldClass = PieceGoodsConstants.LotSerialClassID)]
        public int? UsrPGWtFIFO { get; set; }
        public abstract class usrPGWtFIFO : BqlInt.Field<usrPGWtFIFO> { }
        #endregion

        #endregion
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using PX.Data;
using PX.Data.BQL;
using PX.Data.BQL.Fluent;
using PX.Objects.CS;
using PX.Objects.IN;
using PX.Objects.SO;

namespace Aesthetik.WMS
{
    /// <summary>
    /// Graph extension managing the cross-dock fulfillment workflow.
    ///
    /// Cross-dock allows orders to be fulfilled from rolls that have been physically
    /// received (scanned off a container) but not yet moved to permanent bin locations.
    ///
    /// Manages:
    ///   - RECV-DOCK virtual location lifecycle
    ///   - Container-level put-away tracking dashboard
    ///   - Cross-dock pick routing (RECV-DOCK vs bin stock)
    ///   - Age-based put-away priority escalation
    ///   - Status transitions: In-Transit → Receiving → Available/Shipped
    ///
    /// Target: Acumatica 2024 R2
    /// </summary>
    public class CrossDockManager : PXGraphExtension<SOShipmentEntry>
    {
        public static bool IsActive() => true;

        #region Configuration

        /// <summary>
        /// Loads cross-dock configuration from INSetup.
        /// </summary>
        private CrossDockConfig GetConfig()
        {
            var setup = SelectFrom<INSetup>.View.ReadOnly.SelectSingleBound(Base, null);
            var ext = ((INSetup)setup)?.GetExtension<INSetupExt>();

            return new CrossDockConfig
            {
                Enabled = ext?.UsrPGCrossDock ?? PieceGoodsConstants.DefaultCrossDockEnabled,
                AgeDaysThreshold = ext?.UsrPGXDockAge ?? PieceGoodsConstants.DefaultCrossDockAgeDays,
            };
        }

        #endregion

        #region Container Dashboard

        /// <summary>
        /// Gets container tracking summary for the cross-dock dashboard.
        /// Groups all piece goods serials by container number and calculates
        /// aggregate statistics for each container.
        /// </summary>
        public List<ContainerStatus> GetContainerDashboard(int warehouseID)
        {
            var config = GetConfig();
            if (!config.Enabled) return new List<ContainerStatus>();

            // Query all piece goods serials at this warehouse with a container number
            var allSerials = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.siteID.IsEqual<@P.AsInt>>
                .View.ReadOnly.Select(Base, warehouseID);

            var serialsWithContainer = new List<(INLotSerialStatus Status, INLotSerialStatusExt Ext)>();

            foreach (PXResult<INLotSerialStatus> row in allSerials)
            {
                var status = (INLotSerialStatus)row;
                var ext = status.GetExtension<INLotSerialStatusExt>();
                if (!string.IsNullOrEmpty(ext?.UsrContainerNo))
                {
                    serialsWithContainer.Add((status, ext));
                }
            }

            // Group by container and compute stats
            var containerGroups = serialsWithContainer
                .GroupBy(s => s.Ext.UsrContainerNo, StringComparer.OrdinalIgnoreCase);

            var results = new List<ContainerStatus>();

            foreach (var group in containerGroups)
            {
                var items = group.ToList();
                int total = items.Count;
                int receiving = items.Count(i =>
                    i.Ext.UsrInventoryStatus == PieceGoodsConstants.InvStatus_Receiving);
                int putAway = items.Count(i =>
                    i.Ext.UsrInventoryStatus == PieceGoodsConstants.InvStatus_Available ||
                    i.Ext.UsrInventoryStatus == PieceGoodsConstants.InvStatus_PutAway);
                int inTransit = items.Count(i =>
                    i.Ext.UsrInventoryStatus == PieceGoodsConstants.InvStatus_InTransit);

                // Cross-dock picked = rolls that were shipped directly from receiving
                // (no longer in inventory, tracked via shipment history)
                int crossDockPicked = total - receiving - putAway - inTransit;

                // Calculate age on dock from the earliest receiving timestamp
                // Using the status record's LastModifiedDateTime as a proxy
                DateTime? earliestReceived = items
                    .Where(i => i.Ext.UsrInventoryStatus == PieceGoodsConstants.InvStatus_Receiving)
                    .Select(i => i.Status.LastModifiedDateTime)
                    .Where(d => d.HasValue)
                    .OrderBy(d => d)
                    .FirstOrDefault();

                int ageOnDock = earliestReceived.HasValue
                    ? (DateTime.Today - earliestReceived.Value.Date).Days
                    : 0;

                results.Add(new ContainerStatus
                {
                    ContainerNumber = group.Key,
                    TotalRolls = total,
                    CrossDockPicked = Math.Max(0, crossDockPicked),
                    PutAway = putAway,
                    RemainingOnDock = receiving,
                    InTransit = inTransit,
                    AgeOnDockDays = ageOnDock,
                    PutAwayPercent = total > 0 ? Math.Round(putAway * 100m / total, 1) : 0,
                    FirstReceivedDate = earliestReceived,
                    IsOverAgeThreshold = ageOnDock > config.AgeDaysThreshold,
                });
            }

            // Sort: over-age containers first, then by age descending
            return results
                .OrderByDescending(c => c.IsOverAgeThreshold)
                .ThenByDescending(c => c.AgeOnDockDays)
                .ToList();
        }

        #endregion

        #region Status Transitions

        /// <summary>
        /// Transitions a roll's status from In-Transit to Receiving.
        /// Called when a roll is physically scanned off a container.
        /// Makes the roll immediately available for cross-dock picking.
        /// </summary>
        /// <param name="inventoryID">Inventory item ID.</param>
        /// <param name="serialNbr">Roll serial number.</param>
        /// <param name="recvDockLocationID">Location ID of the RECV-DOCK location.</param>
        public void TransitionToReceiving(int inventoryID, string serialNbr, int recvDockLocationID)
        {
            var config = GetConfig();

            var statusRow = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                    .And<INLotSerialStatus.lotSerialNbr.IsEqual<@P.AsString>>>
                .View.Select(Base, inventoryID, serialNbr);

            if (statusRow == null)
                throw new PXException($"Serial '{serialNbr}' not found for inventory ID {inventoryID}.");

            var status = (INLotSerialStatus)statusRow;
            var ext = status.GetExtension<INLotSerialStatusExt>();

            // Validate current status
            if (ext.UsrInventoryStatus != PieceGoodsConstants.InvStatus_InTransit)
            {
                throw new PXException(
                    $"Serial '{serialNbr}' cannot transition to Receiving. " +
                    $"Current status is '{ext.UsrInventoryStatus}', expected '{PieceGoodsConstants.InvStatus_InTransit}'.");
            }

            // Update status and location
            ext.UsrInventoryStatus = PieceGoodsConstants.InvStatus_Receiving;
            status.LocationID = recvDockLocationID;

            Base.Caches[typeof(INLotSerialStatus)].Update(status);
            Base.Actions.PressSave();
        }

        /// <summary>
        /// Transitions a roll from Receiving to Available (put-away complete).
        /// Called when a roll is scanned into its permanent bin location.
        /// If the actual bin differs from PreAssignedBin, updates the record.
        /// </summary>
        public void TransitionToAvailable(int inventoryID, string serialNbr, int actualLocationID)
        {
            var statusRow = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                    .And<INLotSerialStatus.lotSerialNbr.IsEqual<@P.AsString>>>
                .View.Select(Base, inventoryID, serialNbr);

            if (statusRow == null)
                throw new PXException($"Serial '{serialNbr}' not found.");

            var status = (INLotSerialStatus)statusRow;
            var ext = status.GetExtension<INLotSerialStatusExt>();

            if (ext.UsrInventoryStatus != PieceGoodsConstants.InvStatus_Receiving)
            {
                throw new PXException(
                    $"Serial '{serialNbr}' cannot transition to Available. " +
                    $"Current status is '{ext.UsrInventoryStatus}', expected '{PieceGoodsConstants.InvStatus_Receiving}'.");
            }

            // Resolve the actual bin location CD for the record
            var actualLoc = SelectFrom<INLocation>
                .Where<INLocation.locationID.IsEqual<@P.AsInt>>
                .View.ReadOnly.Select(Base, actualLocationID);

            string actualBinCD = actualLoc != null ? ((INLocation)actualLoc).LocationCD : null;

            // Check if actual bin differs from pre-assigned
            if (!string.IsNullOrEmpty(ext.UsrPreAssignedBin) &&
                !string.Equals(ext.UsrPreAssignedBin, actualBinCD, StringComparison.OrdinalIgnoreCase))
            {
                // Update pre-assigned bin to reflect actual placement
                ext.UsrPreAssignedBin = actualBinCD;

                // TODO: Recalculate any pending pick instructions that reference
                // this roll's old pre-assigned bin. This would involve querying
                // SOShipLineSplit records allocated to this serial and updating
                // their location references.
            }

            ext.UsrInventoryStatus = PieceGoodsConstants.InvStatus_Available;
            status.LocationID = actualLocationID;

            Base.Caches[typeof(INLotSerialStatus)].Update(status);
            Base.Actions.PressSave();
        }

        /// <summary>
        /// Marks a roll as shipped directly from cross-dock (bypasses put-away).
        /// Called when a RECV-DOCK roll is picked for a shipment.
        /// The roll's inventory status is not updated here — the standard SO shipment
        /// process handles inventory issuance. This method updates the piece goods
        /// tracking fields only.
        /// </summary>
        public void TransitionToShipped(int inventoryID, string serialNbr)
        {
            var statusRow = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                    .And<INLotSerialStatus.lotSerialNbr.IsEqual<@P.AsString>>>
                .View.Select(Base, inventoryID, serialNbr);

            if (statusRow == null) return; // May already be consumed by shipment

            var status = (INLotSerialStatus)statusRow;
            var ext = status.GetExtension<INLotSerialStatusExt>();

            // Only transition from Receiving status (cross-dock path)
            if (ext.UsrInventoryStatus == PieceGoodsConstants.InvStatus_Receiving)
            {
                // The standard SO shipment confirmation will handle the inventory
                // deduction. We just need to note this was a cross-dock fulfillment
                // for dashboard tracking purposes. The status record will be consumed
                // by the shipment release process.

                // No additional status update needed — the inventory will be zeroed
                // out by the shipment. Container dashboard calculates cross-dock
                // picks as total - receiving - putaway - intransit.
            }
        }

        #endregion

        #region Put-Away Priority

        /// <summary>
        /// Returns a prioritized list of rolls in RECV-DOCK that should be put away next.
        /// Priority logic:
        ///   1. Rolls with no pending orders → put away first (not needed on dock)
        ///   2. Rolls past CrossDockAgeDays threshold → escalated priority
        ///   3. Rolls allocated to future orders → put away last (may ship first)
        /// </summary>
        public List<PutAwayCandidate> GetPutAwayQueue(int warehouseID)
        {
            var config = GetConfig();
            if (!config.Enabled) return new List<PutAwayCandidate>();

            // Get all rolls currently in Receiving status
            var receivingRolls = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.siteID.IsEqual<@P.AsInt>>
                .View.ReadOnly.Select(Base, warehouseID);

            var candidates = new List<PutAwayCandidate>();

            foreach (PXResult<INLotSerialStatus> row in receivingRolls)
            {
                var status = (INLotSerialStatus)row;
                var ext = status.GetExtension<INLotSerialStatusExt>();

                if (ext?.UsrInventoryStatus != PieceGoodsConstants.InvStatus_Receiving)
                    continue;

                // Calculate days on dock
                int daysOnDock = status.LastModifiedDateTime.HasValue
                    ? (DateTime.Today - status.LastModifiedDateTime.Value.Date).Days
                    : 0;

                // Check for pending order allocations against this serial
                bool hasPendingOrders = HasPendingOrderAllocations(
                    status.InventoryID.Value, status.LotSerialNbr);

                // Look up item CD for display
                var item = SelectFrom<InventoryItem>
                    .Where<InventoryItem.inventoryID.IsEqual<@P.AsInt>>
                    .View.ReadOnly.Select(Base, status.InventoryID);
                string sku = item != null ? ((InventoryItem)item).InventoryCD?.Trim() : "";

                // Priority scoring: lower number = higher priority
                int priority;
                if (!hasPendingOrders && daysOnDock > config.AgeDaysThreshold)
                    priority = 1;  // No orders + over age = put away immediately
                else if (!hasPendingOrders)
                    priority = 2;  // No orders = put away next
                else if (daysOnDock > config.AgeDaysThreshold)
                    priority = 3;  // Has orders but over age = escalated
                else
                    priority = 4;  // Has orders, not over age = put away last

                candidates.Add(new PutAwayCandidate
                {
                    SerialNbr = status.LotSerialNbr,
                    InventoryID = status.InventoryID.Value,
                    SKU = sku,
                    PreAssignedBin = ext.UsrPreAssignedBin,
                    DaysOnDock = daysOnDock,
                    HasPendingOrders = hasPendingOrders,
                    Priority = priority,
                    ContainerNumber = ext.UsrContainerNo,
                });
            }

            return candidates.OrderBy(c => c.Priority).ThenByDescending(c => c.DaysOnDock).ToList();
        }

        /// <summary>
        /// Checks whether a serial has any pending SO shipment allocations.
        /// Returns true if any open shipment line references this serial.
        /// </summary>
        private bool HasPendingOrderAllocations(int inventoryID, string serialNbr)
        {
            var allocation = SelectFrom<SOShipLineSplit>
                .Where<SOShipLineSplit.inventoryID.IsEqual<@P.AsInt>
                    .And<SOShipLineSplit.lotSerialNbr.IsEqual<@P.AsString>>>
                .View.ReadOnly.Select(Base, inventoryID, serialNbr);

            return allocation != null && allocation.Count > 0;
        }

        #endregion

        #region RECV-DOCK Location Helper

        /// <summary>
        /// Resolves the RECV-DOCK location ID for a given warehouse.
        /// Returns null if the location does not exist.
        /// </summary>
        public int? GetRecvDockLocationID(int warehouseID)
        {
            var location = SelectFrom<INLocation>
                .Where<INLocation.siteID.IsEqual<@P.AsInt>
                    .And<INLocation.locationCD.IsEqual<@P.AsString>>>
                .View.ReadOnly.Select(Base, warehouseID, PieceGoodsConstants.Location_RecvDock);

            return location != null ? ((INLocation)location).LocationID : null;
        }

        #endregion

        #region Supporting Types

        /// <summary>Cross-dock configuration loaded from INSetup.</summary>
        private class CrossDockConfig
        {
            public bool Enabled { get; set; }
            public int AgeDaysThreshold { get; set; }
        }

        /// <summary>Container-level tracking for the cross-dock dashboard.</summary>
        public class ContainerStatus
        {
            public string ContainerNumber { get; set; }
            public int TotalRolls { get; set; }
            public int CrossDockPicked { get; set; }
            public int PutAway { get; set; }
            public int RemainingOnDock { get; set; }
            public int InTransit { get; set; }
            public int AgeOnDockDays { get; set; }
            public decimal PutAwayPercent { get; set; }
            public DateTime? FirstReceivedDate { get; set; }
            public bool IsOverAgeThreshold { get; set; }
        }

        /// <summary>A roll in RECV-DOCK prioritized for put-away.</summary>
        public class PutAwayCandidate
        {
            public string SerialNbr { get; set; }
            public int InventoryID { get; set; }
            public string SKU { get; set; }
            public string PreAssignedBin { get; set; }
            public int DaysOnDock { get; set; }
            public bool HasPendingOrders { get; set; }
            public int Priority { get; set; }
            public string ContainerNumber { get; set; }
        }

        #endregion
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using PX.Data;
using PX.Data.BQL;
using PX.Data.BQL.Fluent;
using PX.Objects.CS;
using PX.Objects.IN;
using PX.Objects.SO;

namespace Aesthetik.WMS
{
    /// <summary>
    /// Graph extension for SOShipmentEntry that replaces the default FIFO/FEFO
    /// pick suggestion logic with textile-aware allocation.
    ///
    /// Evaluates all available rolls — including RECV-DOCK and In-Transit — and
    /// ranks them using a configurable weighted scoring algorithm:
    ///   - Exact Match (50):    Roll yardage == ordered qty
    ///   - Minimize Remnant (30): Closest yardage above ordered qty
    ///   - Dye Lot Match (15):    Same dye lot as other order lines
    ///   - Location Pref (10):    Bin stock preferred over RECV-DOCK
    ///   - FIFO Age (5):          Older rolls score higher (tiebreaker)
    ///
    /// Runs at shipment creation. Warehouse staff can override during picking.
    ///
    /// Target: Acumatica 2024 R2
    /// </summary>
    public class TextilePickOptimizer : PXGraphExtension<SOShipmentEntry>
    {
        public static bool IsActive() => true;

        #region Allocation Override

        /// <summary>
        /// Generates textile-aware pick suggestions for all PIECEGOODS lines
        /// on the current shipment. Returns a list of allocation results
        /// that can be applied to SOShipLineSplit records.
        /// </summary>
        public List<AllocationResult> GeneratePickSuggestions(SOShipment shipment)
        {
            if (shipment == null) return new List<AllocationResult>();

            var weights = LoadWeights();
            var results = new List<AllocationResult>();

            // Load all shipment lines for PIECEGOODS items
            var shipLines = SelectFrom<SOShipLine>
                .Where<SOShipLine.shipmentNbr.IsEqual<@P.AsString>>
                .View.ReadOnly.Select(Base, shipment.ShipmentNbr)
                .Select(r => (SOShipLine)r)
                .Where(l => IsPieceGoodsItem(l.InventoryID))
                .ToList();

            if (shipLines.Count == 0) return results;

            // Track assignments to prevent double-allocation
            var assignedSerials = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            // Track dye lot assignments for multi-line matching
            var dyeLotByItem = new Dictionary<int, string>();

            // Sort lines by quantity (larger orders first for better fit)
            var sortedLines = shipLines.OrderByDescending(l => l.ShippedQty ?? l.OrigOrderQty ?? 0);

            foreach (var line in sortedLines)
            {
                if (line.InventoryID == null) continue;

                decimal orderedQty = line.ShippedQty ?? line.OrigOrderQty ?? 0;
                if (orderedQty <= 0) continue;

                int inventoryID = line.InventoryID.Value;

                // Determine target dye lot if other lines for this item already assigned
                string targetDyeLot = null;
                dyeLotByItem.TryGetValue(inventoryID, out targetDyeLot);

                // Get all candidate rolls
                var candidates = GetCandidateRolls(inventoryID, line.SiteID);

                // Remove already-assigned serials
                candidates = candidates.Where(c => !assignedSerials.Contains(c.LotSerialNbr)).ToList();

                if (candidates.Count == 0)
                {
                    results.Add(new AllocationResult
                    {
                        ShipLineNbr = line.LineNbr,
                        AssignedSerial = null,
                        Score = 0,
                        ErrorMessage = "No eligible rolls available",
                    });
                    continue;
                }

                // Score each candidate
                var scored = candidates
                    .Select(c => new
                    {
                        Candidate = c,
                        Score = ScoreRoll(c, orderedQty, targetDyeLot, weights),
                    })
                    .Where(s => s.Score >= 0) // Exclude disqualified rolls
                    .OrderByDescending(s => s.Score)
                    .ToList();

                if (scored.Count == 0)
                {
                    results.Add(new AllocationResult
                    {
                        ShipLineNbr = line.LineNbr,
                        AssignedSerial = null,
                        Score = 0,
                        ErrorMessage = "No rolls with sufficient yardage",
                    });
                    continue;
                }

                var best = scored.First();
                bool requiresCut = best.Candidate.ActualYardage > orderedQty;

                // Track assignment
                assignedSerials.Add(best.Candidate.LotSerialNbr);

                // Track dye lot for multi-line matching
                if (!string.IsNullOrEmpty(best.Candidate.DyeLot))
                    dyeLotByItem[inventoryID] = best.Candidate.DyeLot;

                results.Add(new AllocationResult
                {
                    ShipLineNbr = line.LineNbr,
                    AssignedSerial = best.Candidate.LotSerialNbr,
                    AssignedYardage = best.Candidate.ActualYardage,
                    RequiresCut = requiresCut,
                    ExpectedRemnant = requiresCut
                        ? best.Candidate.ActualYardage - orderedQty
                        : (decimal?)null,
                    Score = best.Score,
                    SourceLocation = best.Candidate.InventoryStatus ==
                        PieceGoodsConstants.InvStatus_Receiving
                            ? PieceGoodsConstants.Location_RecvDock
                            : best.Candidate.LocationCD,
                    DyeLot = best.Candidate.DyeLot,
                });
            }

            return results;
        }

        /// <summary>
        /// Applies pick suggestions to the shipment by updating SOShipLineSplit records.
        /// </summary>
        public void ApplyPickSuggestions(SOShipment shipment, List<AllocationResult> suggestions)
        {
            if (shipment == null || suggestions == null) return;

            foreach (var suggestion in suggestions.Where(s => s.AssignedSerial != null))
            {
                // Find the corresponding split record for this shipment line
                var splits = SelectFrom<SOShipLineSplit>
                    .Where<SOShipLineSplit.shipmentNbr.IsEqual<@P.AsString>
                        .And<SOShipLineSplit.lineNbr.IsEqual<@P.AsInt>>>
                    .View.Select(Base, shipment.ShipmentNbr, suggestion.ShipLineNbr);

                if (splits == null || splits.Count == 0) continue;

                var split = (SOShipLineSplit)splits;
                split.LotSerialNbr = suggestion.AssignedSerial;

                Base.Caches[typeof(SOShipLineSplit)].Update(split);
            }

            Base.Actions.PressSave();
        }

        #endregion

        #region Candidate Loading

        /// <summary>
        /// Loads all candidate rolls for a given item at a specific warehouse.
        /// Includes Available, Receiving (cross-dock), and In-Transit rolls.
        /// Excludes defective rolls.
        /// </summary>
        private List<RollCandidate> GetCandidateRolls(int inventoryID, int? siteID)
        {
            var candidates = new List<RollCandidate>();

            var allSerials = siteID.HasValue
                ? SelectFrom<INLotSerialStatus>
                    .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                        .And<INLotSerialStatus.siteID.IsEqual<@P.AsInt>>>
                    .View.ReadOnly.Select(Base, inventoryID, siteID.Value)
                : SelectFrom<INLotSerialStatus>
                    .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>>
                    .View.ReadOnly.Select(Base, inventoryID);

            foreach (PXResult<INLotSerialStatus> row in allSerials)
            {
                var status = (INLotSerialStatus)row;
                var ext = status.GetExtension<INLotSerialStatusExt>();

                if (ext == null) continue;

                // Skip defective rolls
                if (ext.UsrDefectFlag == true) continue;

                // Skip rolls not in a pickable status
                string invStatus = ext.UsrInventoryStatus;
                if (invStatus != PieceGoodsConstants.InvStatus_Available &&
                    invStatus != PieceGoodsConstants.InvStatus_Receiving &&
                    invStatus != PieceGoodsConstants.InvStatus_InTransit &&
                    invStatus != PieceGoodsConstants.InvStatus_PutAway)
                    continue;

                // Skip rolls with zero yardage
                if ((ext.UsrActualYardage ?? 0) <= 0) continue;

                // Resolve location CD for display
                string locationCD = null;
                if (status.LocationID.HasValue)
                {
                    var loc = SelectFrom<INLocation>
                        .Where<INLocation.locationID.IsEqual<@P.AsInt>>
                        .View.ReadOnly.Select(Base, status.LocationID);
                    locationCD = loc != null ? ((INLocation)loc).LocationCD : null;
                }

                candidates.Add(new RollCandidate
                {
                    LotSerialNbr = status.LotSerialNbr,
                    InventoryID = status.InventoryID.Value,
                    SiteID = status.SiteID.Value,
                    LocationID = status.LocationID ?? 0,
                    LocationCD = locationCD,
                    ActualYardage = ext.UsrActualYardage ?? 0,
                    DyeLot = ext.UsrDyeLot,
                    ShadeCode = ext.UsrShadeCode,
                    Width = ext.UsrWidth,
                    DefectFlag = ext.UsrDefectFlag ?? false,
                    InventoryStatus = invStatus,
                    ReceiptDate = status.LastModifiedDateTime?.Date,
                    ContainerNumber = ext.UsrContainerNo,
                });
            }

            return candidates;
        }

        #endregion

        #region Scoring Engine

        /// <summary>
        /// Scores a candidate roll for a given order line.
        /// Higher score = better candidate. Returns -1 to disqualify.
        /// </summary>
        public decimal ScoreRoll(
            RollCandidate candidate,
            decimal orderedQty,
            string targetDyeLot,
            OptimizerWeights weights)
        {
            // Disqualify if roll doesn't have enough yardage
            if (candidate.ActualYardage < orderedQty)
                return -1;

            decimal score = 0;

            // ── Exact match (roll yardage ≈ ordered qty within 0.1 yd) ──
            if (Math.Abs(candidate.ActualYardage - orderedQty) <= 0.1m)
            {
                score += weights.ExactMatch;
            }
            else
            {
                // ── Minimize remnant ────────────────────────────────────
                decimal remnant = candidate.ActualYardage - orderedQty;
                // Inverse: smaller remnant = higher score
                // Scale: a 1-yd remnant scores near max; 100+ yd remnant scores near 0
                decimal remnantScore = Math.Max(0, 1 - (remnant / Math.Max(candidate.ActualYardage, 1)));
                score += weights.MinimizeRemnant * remnantScore;
            }

            // ── Dye lot match ───────────────────────────────────────────
            if (!string.IsNullOrEmpty(targetDyeLot) &&
                string.Equals(candidate.DyeLot, targetDyeLot, StringComparison.OrdinalIgnoreCase))
            {
                score += weights.DyeLotMatch;
            }

            // ── Location preference ─────────────────────────────────────
            switch (candidate.InventoryStatus)
            {
                case PieceGoodsConstants.InvStatus_Available:
                case PieceGoodsConstants.InvStatus_PutAway:
                    score += weights.LocationPreference;
                    break;
                case PieceGoodsConstants.InvStatus_Receiving:
                    score += weights.LocationPreference * 0.5m;
                    break;
                case PieceGoodsConstants.InvStatus_InTransit:
                    score += weights.InTransitPenalty; // Typically negative
                    break;
            }

            // ── FIFO age (tiebreaker) ───────────────────────────────────
            if (candidate.ReceiptDate.HasValue)
            {
                int ageDays = Math.Max(0, (DateTime.Today - candidate.ReceiptDate.Value).Days);
                decimal ageFactor = Math.Min(ageDays / 365m, 1m);
                score += weights.FIFOAge * ageFactor;
            }

            return score;
        }

        #endregion

        #region Configuration

        /// <summary>Loads optimizer weights from INSetup.</summary>
        private OptimizerWeights LoadWeights()
        {
            var setup = SelectFrom<INSetup>.View.ReadOnly.SelectSingleBound(Base, null);
            var ext = ((INSetup)setup)?.GetExtension<INSetupExt>();
            return OptimizerWeights.FromSetup(ext);
        }

        /// <summary>Checks if an item uses the PIECEGOODS class.</summary>
        private bool IsPieceGoodsItem(int? inventoryID)
        {
            if (inventoryID == null) return false;

            var item = SelectFrom<InventoryItem>
                .Where<InventoryItem.inventoryID.IsEqual<@P.AsInt>>
                .View.ReadOnly.Select(Base, inventoryID);

            if (item == null) return false;

            return string.Equals(
                ((InventoryItem)item).LotSerClassID,
                PieceGoodsConstants.LotSerialClassID,
                StringComparison.OrdinalIgnoreCase);
        }

        #endregion

        #region Supporting Types

        /// <summary>Candidate roll for pick allocation.</summary>
        public class RollCandidate
        {
            public string LotSerialNbr { get; set; }
            public int InventoryID { get; set; }
            public int SiteID { get; set; }
            public int LocationID { get; set; }
            public string LocationCD { get; set; }
            public decimal ActualYardage { get; set; }
            public string DyeLot { get; set; }
            public string ShadeCode { get; set; }
            public decimal? Width { get; set; }
            public bool DefectFlag { get; set; }
            public string InventoryStatus { get; set; }
            public DateTime? ReceiptDate { get; set; }
            public string ContainerNumber { get; set; }
        }

        /// <summary>Configurable weights loaded from INSetupExt.</summary>
        public class OptimizerWeights
        {
            public int ExactMatch { get; set; } = PieceGoodsConstants.DefaultWeight_ExactMatch;
            public int MinimizeRemnant { get; set; } = PieceGoodsConstants.DefaultWeight_MinimizeRemnant;
            public int DyeLotMatch { get; set; } = PieceGoodsConstants.DefaultWeight_DyeLotMatch;
            public int LocationPreference { get; set; } = PieceGoodsConstants.DefaultWeight_LocationPref;
            public int FIFOAge { get; set; } = PieceGoodsConstants.DefaultWeight_FIFOAge;
            public int InTransitPenalty { get; set; } = PieceGoodsConstants.DefaultInTransitAllocWeight;

            public static OptimizerWeights FromSetup(INSetupExt ext)
            {
                if (ext == null) return new OptimizerWeights();

                return new OptimizerWeights
                {
                    ExactMatch = ext.UsrPGWtExact ?? PieceGoodsConstants.DefaultWeight_ExactMatch,
                    MinimizeRemnant = ext.UsrPGWtRemnant ?? PieceGoodsConstants.DefaultWeight_MinimizeRemnant,
                    DyeLotMatch = ext.UsrPGWtDyeLot ?? PieceGoodsConstants.DefaultWeight_DyeLotMatch,
                    LocationPreference = ext.UsrPGWtLocation ?? PieceGoodsConstants.DefaultWeight_LocationPref,
                    FIFOAge = ext.UsrPGWtFIFO ?? PieceGoodsConstants.DefaultWeight_FIFOAge,
                    InTransitPenalty = ext.UsrPGInTransitWt ?? PieceGoodsConstants.DefaultInTransitAllocWeight,
                };
            }
        }

        /// <summary>Result of an allocation run for a single shipment line.</summary>
        public class AllocationResult
        {
            public int? ShipLineNbr { get; set; }
            public string AssignedSerial { get; set; }
            public decimal AssignedYardage { get; set; }
            public bool RequiresCut { get; set; }
            public decimal? ExpectedRemnant { get; set; }
            public decimal Score { get; set; }
            public string SourceLocation { get; set; }
            public string DyeLot { get; set; }
            public string ErrorMessage { get; set; }
        }

        #endregion
    }
}

using System;
using PX.Data;
using PX.Data.BQL;
using PX.Data.BQL.Fluent;
using PX.Objects.CS;
using PX.Objects.IN;
using PX.Objects.PO;

namespace Aesthetik.WMS
{
    /// <summary>
    /// Graph extension for POReceiptEntry (PO.30.20.00 — PO Receipts screen).
    ///
    /// Extends physical receiving for piece goods:
    ///   - Pre-receiving validation: matches scanned rolls against pre-created serials
    ///   - Yardage verification: flags variance between expected and actual
    ///   - Label printing: GS1-128 to Keyence-compatible printer
    ///   - Cross-dock activation: received rolls enter RECV-DOCK immediately
    ///   - Ad-hoc receiving: creates serials on-the-fly for unexpected rolls
    ///
    /// Target: Acumatica 2024 R2
    /// </summary>
    public class PieceGoodsReceivingExt : PXGraphExtension<POReceiptEntry>
    {
        public static bool IsActive() => true;

        #region Pre-Receiving Validation

        /// <summary>
        /// Processes a barcode scan during PO receiving for piece goods items.
        /// Matches the scanned roll against pre-created serial records and handles
        /// both pre-received and ad-hoc receiving scenarios.
        /// </summary>
        /// <param name="barcode">Scanned barcode data from Keyence scanner.</param>
        /// <param name="receiptLine">The current PO receipt line being processed.</param>
        /// <returns>Result indicating what action the operator should take next.</returns>
        public ReceivingScanResult ProcessReceivingScan(string barcode, POReceiptLine receiptLine)
        {
            if (string.IsNullOrEmpty(barcode) || receiptLine == null)
                return ReceivingScanResult.Error("Invalid scan data.");

            if (!IsPieceGoodsLine(receiptLine))
                return ReceivingScanResult.NotPieceGoods();

            // Parse the barcode
            if (!BarcodeParser.TryParseGS1128(barcode, out GS1128Result parsed))
                return ReceivingScanResult.Error("Cannot parse barcode.");

            string effectiveSerial = parsed.EffectiveSerial;
            int inventoryID = receiptLine.InventoryID.Value;

            // Try to match against a pre-created serial (In-Transit status)
            var preReceived = FindPreReceivedSerial(inventoryID, effectiveSerial);

            if (preReceived != null)
            {
                // Pre-received roll found — validate and transition to Receiving
                return ProcessPreReceivedRoll(preReceived, receiptLine, parsed);
            }
            else
            {
                // No pre-receiving data — create serial on the fly (ad-hoc)
                return ProcessAdHocReceiving(receiptLine, parsed);
            }
        }

        /// <summary>
        /// Handles a roll that was pre-received (serial already exists with In-Transit status).
        /// Validates yardage, transitions status, and triggers label printing.
        /// </summary>
        private ReceivingScanResult ProcessPreReceivedRoll(
            INLotSerialStatus preReceived,
            POReceiptLine receiptLine,
            GS1128Result parsed)
        {
            var ext = preReceived.GetExtension<INLotSerialStatusExt>();
            var config = GetReceivingConfig();

            // Build result with pre-receiving data
            var result = new ReceivingScanResult
            {
                Success = true,
                IsPreReceived = true,
                SerialNbr = preReceived.LotSerialNbr,
                ExpectedYardage = ext.UsrActualYardage ?? 0,
                DyeLot = ext.UsrDyeLot,
                PreAssignedBin = ext.UsrPreAssignedBin,
                RequiresYardageConfirmation = true,
                Message = $"Pre-received roll matched: {preReceived.LotSerialNbr}. " +
                          $"Expected: {ext.UsrActualYardage:F1} yds. " +
                          $"Bin: {ext.UsrPreAssignedBin ?? "unassigned"}. " +
                          $"Scan @confirm to accept yardage, or enter measured yardage.",
            };

            return result;
        }

        /// <summary>
        /// Handles an unexpected roll with no pre-receiving data.
        /// Creates the serial on the fly and runs immediate bin assignment.
        /// </summary>
        private ReceivingScanResult ProcessAdHocReceiving(
            POReceiptLine receiptLine,
            GS1128Result parsed)
        {
            return new ReceivingScanResult
            {
                Success = true,
                IsPreReceived = false,
                SerialNbr = null, // Will be generated after yardage entry
                RequiresYardageConfirmation = true,
                RequiresManualYardageEntry = true,
                Message = "Roll not pre-received. Enter serial number and yardage to create on the fly.",
            };
        }

        /// <summary>
        /// Confirms the yardage for a pre-received roll and transitions it to Receiving status.
        /// Called when the operator scans @confirm or enters a measured yardage.
        /// </summary>
        /// <param name="inventoryID">Item inventory ID.</param>
        /// <param name="serialNbr">Roll serial number (from pre-receiving).</param>
        /// <param name="actualYardage">Measured yardage (null = accept expected).</param>
        /// <param name="warehouseID">Warehouse ID for RECV-DOCK location lookup.</param>
        public YardageConfirmResult ConfirmYardage(
            int inventoryID, string serialNbr, decimal? actualYardage, int warehouseID)
        {
            var statusRow = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                    .And<INLotSerialStatus.lotSerialNbr.IsEqual<@P.AsString>>>
                .View.Select(Base, inventoryID, serialNbr);

            if (statusRow == null)
                return new YardageConfirmResult { Success = false, ErrorMessage = "Serial not found." };

            var status = (INLotSerialStatus)statusRow;
            var ext = status.GetExtension<INLotSerialStatusExt>();
            var config = GetReceivingConfig();

            decimal expectedYardage = ext.UsrActualYardage ?? 0;
            decimal confirmedYardage = actualYardage ?? expectedYardage;

            // Check variance
            bool hasVariance = false;
            decimal variancePercent = 0;

            if (actualYardage.HasValue && expectedYardage > 0)
            {
                variancePercent = Math.Abs(actualYardage.Value - expectedYardage) / expectedYardage;
                hasVariance = variancePercent > config.YardageVarianceThreshold;
            }

            // Update yardage if actual was provided
            if (actualYardage.HasValue)
                ext.UsrActualYardage = actualYardage.Value;

            // Transition to Receiving status
            ext.UsrInventoryStatus = PieceGoodsConstants.InvStatus_Receiving;

            // Move to RECV-DOCK location
            var recvDockID = GetRecvDockLocationID(warehouseID);
            if (recvDockID.HasValue)
                status.LocationID = recvDockID.Value;

            Base.Caches[typeof(INLotSerialStatus)].Update(status);
            Base.Actions.PressSave();

            // Trigger label printing if auto-print enabled
            string labelData = null;
            if (config.AutoPrintLabel)
            {
                labelData = GenerateLabel(inventoryID, serialNbr, ext.UsrDyeLot);
            }

            return new YardageConfirmResult
            {
                Success = true,
                ConfirmedYardage = confirmedYardage,
                HasVariance = hasVariance,
                VariancePercent = variancePercent,
                LabelData = labelData,
                Message = hasVariance
                    ? $"⚠ VARIANCE: Expected {expectedYardage:F1}, Actual {confirmedYardage:F1} " +
                      $"({variancePercent:P1}). Roll received to RECV-DOCK."
                    : $"✓ Roll {serialNbr} received ({confirmedYardage:F1} yds) → RECV-DOCK. " +
                      $"Cross-dock eligible.",
            };
        }

        /// <summary>
        /// Creates a serial on the fly for ad-hoc receiving (no pre-receiving data).
        /// Generates serial, sets attributes, assigns bin, and transitions to Receiving.
        /// </summary>
        public AdHocReceiveResult ReceiveAdHoc(
            int inventoryID, string sku, decimal yardage, string dyeLot,
            decimal? width, string shadeCode, string containerNumber, int warehouseID)
        {
            var config = GetReceivingConfig();

            // Generate serial number
            var engine = new PreReceivingEngine(Base);
            string serialNbr = string.Format(
                PieceGoodsConstants.SerialFormat, sku, DateTime.Today,
                GetNextAdHocSequence(sku));

            // Create the serial record
            var statusCache = Base.Caches[typeof(INLotSerialStatus)];
            var status = (INLotSerialStatus)statusCache.CreateInstance();
            status.InventoryID = inventoryID;
            status.SiteID = warehouseID;
            status.LotSerialNbr = serialNbr;

            var recvDockID = GetRecvDockLocationID(warehouseID);
            if (recvDockID.HasValue)
                status.LocationID = recvDockID.Value;

            status = (INLotSerialStatus)statusCache.Insert(status);

            var ext = status.GetExtension<INLotSerialStatusExt>();
            ext.UsrActualYardage = yardage;
            ext.UsrDyeLot = dyeLot;
            ext.UsrWidth = width ?? GetDefaultWidth();
            ext.UsrShadeCode = shadeCode;
            ext.UsrContainerNo = containerNumber;
            ext.UsrInventoryStatus = PieceGoodsConstants.InvStatus_Receiving;
            ext.UsrDefectFlag = false;

            statusCache.Update(status);
            Base.Actions.PressSave();

            // Run immediate bin assignment
            engine.AssignBins(
                new System.Collections.Generic.List<string> { serialNbr },
                warehouseID);

            // Print label
            string labelData = null;
            if (config.AutoPrintLabel)
            {
                labelData = GenerateLabel(inventoryID, serialNbr, dyeLot);
            }

            return new AdHocReceiveResult
            {
                Success = true,
                SerialNbr = serialNbr,
                Yardage = yardage,
                LabelData = labelData,
                Message = $"✓ Roll {serialNbr} created ({yardage:F1} yds, lot {dyeLot}) → RECV-DOCK. " +
                          $"Cross-dock eligible.",
            };
        }

        #endregion

        #region Label Printing

        /// <summary>
        /// Generates GS1-128 barcode data for label printing.
        /// Returns the formatted barcode string that can be sent to a Keyence printer.
        /// </summary>
        private string GenerateLabel(int inventoryID, string serialNbr, string dyeLot)
        {
            // Look up item CD for the GTIN/SKU field
            var item = SelectFrom<InventoryItem>
                .Where<InventoryItem.inventoryID.IsEqual<@P.AsInt>>
                .View.ReadOnly.Select(Base, inventoryID);

            string sku = item != null ? ((InventoryItem)item).InventoryCD?.Trim() : "";

            return BarcodeParser.GenerateGS1128Label(sku, serialNbr, dyeLot);
        }

        /// <summary>
        /// Sends label data to the Keyence-compatible printer.
        /// </summary>
        public void PrintLabel(string labelData)
        {
            if (string.IsNullOrEmpty(labelData)) return;

            // Keyence Auto-ID Link printer integration:
            // The printer is accessible via the network and accepts label data
            // in its native format. The actual print command depends on the
            // specific Keyence printer model and Auto-ID Link configuration.
            //
            // Integration pattern:
            //   1. Connect to printer via TCP/IP or HTTP
            //   2. Send label template ID + variable data (barcode string)
            //   3. Printer renders and prints the GS1-128 label
            //
            // The label template is pre-configured on the printer with:
            //   - GS1-128 barcode element
            //   - Human-readable text (SKU, Serial, Dye Lot)
            //   - Company logo
            //
            // For production deployment, the printer IP and template ID
            // are configured in Acumatica user preferences or warehouse setup.

            // NOTE: Actual printer communication will be implemented during
            // Phase 6 hardware integration testing with the Keyence BT-A500.
        }

        #endregion

        #region Helper Methods

        /// <summary>Checks if a PO receipt line uses the PIECEGOODS class.</summary>
        protected bool IsPieceGoodsLine(POReceiptLine line)
        {
            if (line?.InventoryID == null) return false;

            var item = SelectFrom<InventoryItem>
                .Where<InventoryItem.inventoryID.IsEqual<@P.AsInt>>
                .View.ReadOnly.Select(Base, line.InventoryID);

            if (item == null) return false;

            return string.Equals(
                ((InventoryItem)item).LotSerClassID,
                PieceGoodsConstants.LotSerialClassID,
                StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>Finds a pre-created serial with In-Transit status.</summary>
        protected INLotSerialStatus FindPreReceivedSerial(int inventoryID, string serialNbr)
        {
            if (string.IsNullOrEmpty(serialNbr)) return null;

            var result = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                    .And<INLotSerialStatus.lotSerialNbr.IsEqual<@P.AsString>>>
                .View.ReadOnly.Select(Base, inventoryID, serialNbr);

            if (result == null) return null;

            var status = (INLotSerialStatus)result;
            var ext = status.GetExtension<INLotSerialStatusExt>();

            // Only match if status is In-Transit (pre-received but not physically received)
            if (ext?.UsrInventoryStatus == PieceGoodsConstants.InvStatus_InTransit)
                return status;

            return null;
        }

        /// <summary>Gets RECV-DOCK location ID for a warehouse.</summary>
        private int? GetRecvDockLocationID(int warehouseID)
        {
            var location = SelectFrom<INLocation>
                .Where<INLocation.siteID.IsEqual<@P.AsInt>
                    .And<INLocation.locationCD.IsEqual<@P.AsString>>>
                .View.ReadOnly.Select(Base, warehouseID, PieceGoodsConstants.Location_RecvDock);

            return location != null ? ((INLocation)location).LocationID : null;
        }

        /// <summary>Gets default fabric width in inches.</summary>
        private decimal GetDefaultWidth()
        {
            return 54.0m;
        }

        /// <summary>Gets next sequence number for ad-hoc serial generation.</summary>
        private int GetNextAdHocSequence(string sku)
        {
            string prefix = $"{sku}-{DateTime.Today:yyMMdd}-";

            var existing = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.lotSerialNbr.IsLike<@P.AsString>>
                .View.ReadOnly.Select(Base, prefix + "%");

            int maxSeq = 0;
            foreach (PXResult<INLotSerialStatus> row in existing)
            {
                var s = (INLotSerialStatus)row;
                if (s.LotSerialNbr.Length > prefix.Length)
                {
                    // Handle both regular serials and cut serials (with -C suffix)
                    string seqPart = s.LotSerialNbr.Substring(prefix.Length);
                    int dashIdx = seqPart.IndexOf('-');
                    if (dashIdx > 0) seqPart = seqPart.Substring(0, dashIdx);

                    if (int.TryParse(seqPart, out int seq) && seq > maxSeq)
                        maxSeq = seq;
                }
            }

            return maxSeq + 1;
        }

        /// <summary>Loads receiving configuration from INSetup.</summary>
        private ReceivingConfig GetReceivingConfig()
        {
            var setup = SelectFrom<INSetup>.View.ReadOnly.SelectSingleBound(Base, null);
            var ext = ((INSetup)setup)?.GetExtension<INSetupExt>();

            return new ReceivingConfig
            {
                AutoPrintLabel = ext?.UsrPGAutoPrint ?? PieceGoodsConstants.DefaultAutoPrintLabel,
                YardageVarianceThreshold = ext?.UsrPGYardageVar
                    ?? PieceGoodsConstants.DefaultYardageVarianceThreshold,
                PreReceivingEnabled = ext?.UsrPGPreRecv
                    ?? PieceGoodsConstants.DefaultPreReceivingEnabled,
            };
        }

        #endregion

        #region Supporting Types

        private class ReceivingConfig
        {
            public bool AutoPrintLabel { get; set; }
            public decimal YardageVarianceThreshold { get; set; }
            public bool PreReceivingEnabled { get; set; }
        }

        /// <summary>Result of processing a barcode scan during receiving.</summary>
        public class ReceivingScanResult
        {
            public bool Success { get; set; }
            public bool IsPreReceived { get; set; }
            public bool IsPieceGoods { get; set; } = true;
            public string SerialNbr { get; set; }
            public decimal ExpectedYardage { get; set; }
            public string DyeLot { get; set; }
            public string PreAssignedBin { get; set; }
            public bool RequiresYardageConfirmation { get; set; }
            public bool RequiresManualYardageEntry { get; set; }
            public string Message { get; set; }
            public string ErrorMessage { get; set; }

            public static ReceivingScanResult Error(string message) =>
                new ReceivingScanResult { Success = false, ErrorMessage = message };

            public static ReceivingScanResult NotPieceGoods() =>
                new ReceivingScanResult { Success = true, IsPieceGoods = false };
        }

        /// <summary>Result of yardage confirmation for a pre-received roll.</summary>
        public class YardageConfirmResult
        {
            public bool Success { get; set; }
            public decimal ConfirmedYardage { get; set; }
            public bool HasVariance { get; set; }
            public decimal VariancePercent { get; set; }
            public string LabelData { get; set; }
            public string Message { get; set; }
            public string ErrorMessage { get; set; }
        }

        /// <summary>Result of ad-hoc receiving (no pre-receiving data).</summary>
        public class AdHocReceiveResult
        {
            public bool Success { get; set; }
            public string SerialNbr { get; set; }
            public decimal Yardage { get; set; }
            public string LabelData { get; set; }
            public string Message { get; set; }
            public string ErrorMessage { get; set; }
        }

        #endregion
    }
}

using PX.Data;
using PX.Objects.CS;
using PX.Objects.IN;

namespace Aesthetik.WMS
{
    /// <summary>
    /// Graph extension for INSetupMaint (IN.20.10.00 — Inventory Preferences).
    /// Surfaces the Piece Goods WMS configuration fields on the Inventory Preferences screen.
    /// This extension adds a "Piece Goods" tab/section to the preferences form.
    /// </summary>
    public class INSetupMaintExt : PXGraphExtension<INSetupMaint>
    {
        public static bool IsActive() => true;

        #region Event Handlers

        /// <summary>
        /// Sets default values for Piece Goods fields when the INSetup record is first created.
        /// </summary>
        protected virtual void _(Events.RowInserted<INSetup> e)
        {
            if (e.Row == null) return;

            var ext = e.Row.GetExtension<INSetupExt>();
            if (ext == null) return;

            ext.UsrPGMinRemnant    ??= PieceGoodsConstants.DefaultMinRemnantYardage;
            ext.UsrPGAutoQtyMode   ??= PieceGoodsConstants.DefaultAutoQuantityMode;
            ext.UsrPGAutoPrint     ??= PieceGoodsConstants.DefaultAutoPrintLabel;
            ext.UsrPGCutSuffix     ??= PieceGoodsConstants.DefaultCutSerialSuffix;
            ext.UsrPGPreRecv       ??= PieceGoodsConstants.DefaultPreReceivingEnabled;
            ext.UsrPGCrossDock     ??= PieceGoodsConstants.DefaultCrossDockEnabled;
            ext.UsrPGXDockAge      ??= PieceGoodsConstants.DefaultCrossDockAgeDays;
            ext.UsrPGInTransitWt   ??= PieceGoodsConstants.DefaultInTransitAllocWeight;
            ext.UsrPGYardageVar    ??= PieceGoodsConstants.DefaultYardageVarianceThreshold;
            ext.UsrPGWtExact       ??= PieceGoodsConstants.DefaultWeight_ExactMatch;
            ext.UsrPGWtRemnant     ??= PieceGoodsConstants.DefaultWeight_MinimizeRemnant;
            ext.UsrPGWtDyeLot      ??= PieceGoodsConstants.DefaultWeight_DyeLotMatch;
            ext.UsrPGWtLocation    ??= PieceGoodsConstants.DefaultWeight_LocationPref;
            ext.UsrPGWtFIFO        ??= PieceGoodsConstants.DefaultWeight_FIFOAge;
        }

        /// <summary>
        /// Validates Piece Goods configuration values on save.
        /// </summary>
        protected virtual void _(Events.RowPersisting<INSetup> e)
        {
            if (e.Row == null || e.Operation == PXDBOperation.Delete) return;

            var ext = e.Row.GetExtension<INSetupExt>();
            if (ext == null) return;

            // Min remnant must be non-negative
            if (ext.UsrPGMinRemnant < 0)
            {
                e.Cache.RaiseExceptionHandling<INSetupExt.usrPGMinRemnant>(
                    e.Row, ext.UsrPGMinRemnant,
                    new PXSetPropertyException("Minimum remnant yardage cannot be negative."));
            }

            // Cross-dock age must be positive
            if (ext.UsrPGXDockAge.HasValue && ext.UsrPGXDockAge <= 0)
            {
                e.Cache.RaiseExceptionHandling<INSetupExt.usrPGXDockAge>(
                    e.Row, ext.UsrPGXDockAge,
                    new PXSetPropertyException("Cross-dock age limit must be greater than zero."));
            }

            // Yardage variance threshold must be between 0 and 1
            if (ext.UsrPGYardageVar < 0 || ext.UsrPGYardageVar > 1)
            {
                e.Cache.RaiseExceptionHandling<INSetupExt.usrPGYardageVar>(
                    e.Row, ext.UsrPGYardageVar,
                    new PXSetPropertyException(
                        "Yardage variance threshold must be between 0.00 and 1.00 (0% to 100%)."));
            }

            // Optimizer weights should be non-negative
            ValidateWeight<INSetupExt.usrPGWtExact>(e.Cache, e.Row, ext.UsrPGWtExact, "Exact Match");
            ValidateWeight<INSetupExt.usrPGWtRemnant>(e.Cache, e.Row, ext.UsrPGWtRemnant, "Minimize Remnant");
            ValidateWeight<INSetupExt.usrPGWtDyeLot>(e.Cache, e.Row, ext.UsrPGWtDyeLot, "Dye Lot Match");
            ValidateWeight<INSetupExt.usrPGWtLocation>(e.Cache, e.Row, ext.UsrPGWtLocation, "Location Preference");
            ValidateWeight<INSetupExt.usrPGWtFIFO>(e.Cache, e.Row, ext.UsrPGWtFIFO, "FIFO Age");

            // Cut serial suffix must contain {0} placeholder
            if (!string.IsNullOrEmpty(ext.UsrPGCutSuffix) && !ext.UsrPGCutSuffix.Contains("{0}"))
            {
                e.Cache.RaiseExceptionHandling<INSetupExt.usrPGCutSuffix>(
                    e.Row, ext.UsrPGCutSuffix,
                    new PXSetPropertyException(
                        "Cut serial suffix must contain {{0}} placeholder for the sequence number."));
            }
        }

        #endregion

        #region Private Helpers

        private static void ValidateWeight<TField>(PXCache cache, INSetup row, int? value, string fieldName)
            where TField : IBqlField
        {
            if (value.HasValue && value < 0)
            {
                cache.RaiseExceptionHandling<TField>(
                    row, value,
                    new PXSetPropertyException($"Pick optimizer weight '{fieldName}' cannot be negative."));
            }
        }

        #endregion
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using PX.Data;
using PX.Data.BQL;
using PX.Data.BQL.Fluent;
using PX.Objects.CS;
using PX.Objects.IN;

namespace Aesthetik.WMS
{
    /// <summary>
    /// Cut-to-order engine for piece goods roll splitting.
    ///
    /// Transaction Approach: Single IN Adjustment (Decrease + Increase)
    ///   - Decrease line: reduces source roll yardage attribute
    ///   - Increase line: creates new cut piece serial with cut yardage
    ///   - Net zero GL impact in a single batch
    ///   - Full PXTransactionScope atomicity
    ///
    /// Concurrency: Pessimistic locking via PXUpdate on source serial row
    /// prevents simultaneous cuts from different scanner stations.
    ///
    /// Target: Acumatica 2024 R2
    /// </summary>
    public class CutToOrderEngine
    {
        private readonly PXGraph _graph;

        public CutToOrderEngine(PXGraph graph)
        {
            _graph = graph ?? throw new ArgumentNullException(nameof(graph));
        }

        #region Configuration

        private CutConfig GetConfig()
        {
            var setup = SelectFrom<INSetup>.View.ReadOnly.SelectSingleBound(_graph, null);
            var setupExt = ((INSetup)setup)?.GetExtension<INSetupExt>();

            return new CutConfig
            {
                MinRemnant = setupExt?.UsrPGMinRemnant
                    ?? PieceGoodsConstants.DefaultMinRemnantYardage,
                CutSerialSuffix = setupExt?.UsrPGCutSuffix
                    ?? PieceGoodsConstants.DefaultCutSerialSuffix,
            };
        }

        private class CutConfig
        {
            public decimal MinRemnant { get; set; }
            public string CutSerialSuffix { get; set; }
        }

        #endregion

        #region Public API

        /// <summary>
        /// Executes a cut-to-order operation on the specified source roll.
        /// Creates a single IN Adjustment with decrease + increase lines.
        /// </summary>
        public CutResult ExecuteCut(
            int inventoryID,
            string sourceSerial,
            decimal cutYardage,
            int warehouseID,
            int locationID)
        {
            var config = GetConfig();

            // ── STEP 1: Validate ───────────────────────────────────────
            var validation = ValidateCutInternal(inventoryID, sourceSerial, cutYardage, config);
            if (!validation.IsValid)
            {
                return new CutResult
                {
                    Success = false,
                    SourceSerial = sourceSerial,
                    ErrorMessage = validation.ErrorMessage,
                    SuggestFullRoll = validation.SuggestFullRoll,
                };
            }

            // ── STEP 2: Acquire lock on source serial ──────────────────
            // Pessimistic lock: select with UPDLOCK to prevent concurrent cuts
            var sourceStatus = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                    .And<INLotSerialStatus.lotSerialNbr.IsEqual<@P.AsString>>>
                .View.Select(_graph, inventoryID, sourceSerial);

            if (sourceStatus == null)
                return new CutResult { Success = false, ErrorMessage = "Source serial not found." };

            var source = (INLotSerialStatus)sourceStatus;
            var sourceExt = source.GetExtension<INLotSerialStatusExt>();

            // ── STEP 3: Generate cut piece serial number ───────────────
            string newSerial = GenerateCutSerial(sourceSerial, config.CutSerialSuffix);

            // ── STEP 4: Create IN Adjustment ───────────────────────────
            string adjustmentRef;
            decimal remainingYardage = (sourceExt.UsrActualYardage ?? 0) - cutYardage;

            using (var scope = new PXTransactionScope())
            {
                var adjustGraph = PXGraph.CreateInstance<INAdjustmentEntry>();

                // Create adjustment header
                var header = new INRegister
                {
                    DocType = INDocType.Adjustment,
                    TranDesc = $"Cut-to-order: {cutYardage:F1} yds from {sourceSerial} → {newSerial}",
                };
                header = adjustGraph.adjustment.Insert(header);

                // Line 1: Decrease source roll (issue the serial being consumed)
                var decreaseLine = new INTran
                {
                    DocType = INDocType.Adjustment,
                    TranType = INTranType.Adjustment,
                    InventoryID = inventoryID,
                    SiteID = warehouseID,
                    LocationID = locationID,
                    LotSerialNbr = sourceSerial,
                    Qty = -1m, // Serial-tracked: 1 unit (the serial itself)
                    TranDesc = $"Source roll decrease: {sourceSerial}",
                };
                adjustGraph.transactions.Insert(decreaseLine);

                // Line 2: Increase — create the source roll back with reduced yardage
                // (We re-receive the source serial with updated attributes)
                var sourceReceiveLine = new INTran
                {
                    DocType = INDocType.Adjustment,
                    TranType = INTranType.Adjustment,
                    InventoryID = inventoryID,
                    SiteID = warehouseID,
                    LocationID = locationID,
                    LotSerialNbr = sourceSerial,
                    Qty = 1m,
                    TranDesc = $"Source roll re-receive: {sourceSerial} ({remainingYardage:F1} yds remaining)",
                };
                adjustGraph.transactions.Insert(sourceReceiveLine);

                // Line 3: Increase — create the cut piece serial
                var cutPieceLine = new INTran
                {
                    DocType = INDocType.Adjustment,
                    TranType = INTranType.Adjustment,
                    InventoryID = inventoryID,
                    SiteID = warehouseID,
                    LocationID = locationID,
                    LotSerialNbr = newSerial,
                    Qty = 1m,
                    TranDesc = $"Cut piece created: {newSerial} ({cutYardage:F1} yds)",
                };
                adjustGraph.transactions.Insert(cutPieceLine);

                // Save and release the adjustment
                adjustGraph.Actions.PressSave();
                adjustmentRef = header.RefNbr;

                // Release the adjustment document
                INDocumentRelease.ReleaseDoc(new List<INRegister> { header }, false);

                scope.Complete();
            }

            // ── STEP 5: Update attributes ──────────────────────────────
            UpdateSourceRollAttributes(inventoryID, sourceSerial, remainingYardage);
            CreateCutPieceAttributes(inventoryID, newSerial, cutYardage, sourceSerial, sourceExt);

            // ── STEP 6: Return result ──────────────────────────────────
            return new CutResult
            {
                Success = true,
                CutPieceSerial = newSerial,
                CutYardage = cutYardage,
                RemnantYardage = remainingYardage,
                SourceSerial = sourceSerial,
                SuggestFullRoll = false,
                AdjustmentRefNbr = adjustmentRef,
            };
        }

        /// <summary>
        /// Validates whether a cut can be performed without executing it.
        /// </summary>
        public CutValidation ValidateCut(
            int inventoryID,
            string sourceSerial,
            decimal requestedYardage)
        {
            var config = GetConfig();
            return ValidateCutInternal(inventoryID, sourceSerial, requestedYardage, config);
        }

        #endregion

        #region Validation

        private CutValidation ValidateCutInternal(
            int inventoryID, string sourceSerial, decimal cutYardage, CutConfig config)
        {
            // Check serial exists
            var statusRow = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                    .And<INLotSerialStatus.lotSerialNbr.IsEqual<@P.AsString>>>
                .View.ReadOnly.Select(_graph, inventoryID, sourceSerial);

            if (statusRow == null)
                return new CutValidation { IsValid = false, ErrorMessage = "Source serial not found." };

            var status = (INLotSerialStatus)statusRow;
            var ext = status.GetExtension<INLotSerialStatusExt>();

            // Check lot/serial class
            var item = SelectFrom<InventoryItem>
                .Where<InventoryItem.inventoryID.IsEqual<@P.AsInt>>
                .View.ReadOnly.Select(_graph, inventoryID);

            if (item == null)
                return new CutValidation { IsValid = false, ErrorMessage = "Inventory item not found." };

            string classID = ((InventoryItem)item).LotSerClassID;
            if (!string.Equals(classID, PieceGoodsConstants.LotSerialClassID,
                StringComparison.OrdinalIgnoreCase))
            {
                return new CutValidation
                {
                    IsValid = false,
                    ErrorMessage = $"Item not assigned to {PieceGoodsConstants.LotSerialClassID} class.",
                };
            }

            // Check defect flag
            if (ext.UsrDefectFlag == true)
            {
                return new CutValidation
                {
                    IsValid = false,
                    ErrorMessage = "Roll is flagged as defective. Override required.",
                };
            }

            // Check yardage
            decimal available = ext.UsrActualYardage ?? 0;
            if (cutYardage <= 0)
                return new CutValidation { IsValid = false, ErrorMessage = "Cut yardage must be positive." };

            if (cutYardage > available)
            {
                return new CutValidation
                {
                    IsValid = false,
                    AvailableYardage = available,
                    ErrorMessage = $"Requested {cutYardage:F1} yds exceeds available {available:F1} yds.",
                };
            }

            decimal remnant = available - cutYardage;

            // Check minimum remnant
            bool suggestFull = remnant > 0 && remnant < config.MinRemnant;

            return new CutValidation
            {
                IsValid = true,
                SuggestFullRoll = suggestFull,
                AvailableYardage = available,
                RemnantYardage = remnant,
            };
        }

        #endregion

        #region Serial Generation

        /// <summary>
        /// Generates a cut piece serial number from the source serial.
        /// Format: [sourceSerial]-C[seq] where seq is the next available number.
        /// </summary>
        private string GenerateCutSerial(string sourceSerial, string suffixFormat)
        {
            // Find existing cuts from this source to determine sequence
            string cutPrefix = sourceSerial + "-C";

            var existingCuts = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.lotSerialNbr.IsLike<@P.AsString>>
                .View.ReadOnly.Select(_graph, cutPrefix + "%");

            int maxSeq = 0;
            foreach (PXResult<INLotSerialStatus> row in existingCuts)
            {
                var s = (INLotSerialStatus)row;
                string suffix = s.LotSerialNbr.Substring(cutPrefix.Length);
                if (int.TryParse(suffix, out int seq) && seq > maxSeq)
                    maxSeq = seq;
            }

            int nextSeq = maxSeq + 1;
            return sourceSerial + string.Format(suffixFormat, nextSeq);
        }

        #endregion

        #region Attribute Management

        /// <summary>
        /// Updates the source roll's ActualYardage after a cut.
        /// </summary>
        private void UpdateSourceRollAttributes(int inventoryID, string sourceSerial, decimal remainingYardage)
        {
            var statusRow = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                    .And<INLotSerialStatus.lotSerialNbr.IsEqual<@P.AsString>>>
                .View.Select(_graph, inventoryID, sourceSerial);

            if (statusRow == null) return;

            var status = (INLotSerialStatus)statusRow;
            var ext = status.GetExtension<INLotSerialStatusExt>();

            ext.UsrActualYardage = remainingYardage;

            _graph.Caches[typeof(INLotSerialStatus)].Update(status);
            _graph.Actions.PressSave();
        }

        /// <summary>
        /// Sets attributes on the newly created cut piece serial.
        /// Inherits dye lot, width, shade code from the source roll.
        /// Sets the SourceRoll traceability link.
        /// </summary>
        private void CreateCutPieceAttributes(
            int inventoryID, string cutSerial, decimal cutYardage,
            string sourceSerial, INLotSerialStatusExt sourceAttrs)
        {
            var statusRow = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                    .And<INLotSerialStatus.lotSerialNbr.IsEqual<@P.AsString>>>
                .View.Select(_graph, inventoryID, cutSerial);

            if (statusRow == null) return;

            var status = (INLotSerialStatus)statusRow;
            var ext = status.GetExtension<INLotSerialStatusExt>();

            // Set cut piece yardage
            ext.UsrActualYardage = cutYardage;

            // Inherit attributes from source roll
            ext.UsrDyeLot = sourceAttrs.UsrDyeLot;
            ext.UsrWidth = sourceAttrs.UsrWidth;
            ext.UsrShadeCode = sourceAttrs.UsrShadeCode;
            ext.UsrContainerNo = sourceAttrs.UsrContainerNo;

            // Set traceability link
            ext.UsrSourceRoll = sourceSerial;

            // Cut piece inherits the source roll's status
            ext.UsrInventoryStatus = sourceAttrs.UsrInventoryStatus;

            // Cut piece has no pre-assigned bin (it goes with the shipment)
            ext.UsrPreAssignedBin = null;

            // Not defective (source was validated before cut)
            ext.UsrDefectFlag = false;

            _graph.Caches[typeof(INLotSerialStatus)].Update(status);
            _graph.Actions.PressSave();
        }

        #endregion

        #region Result Types

        /// <summary>Result of a successful cut-to-order operation.</summary>
        public class CutResult
        {
            public bool Success { get; set; }
            public string CutPieceSerial { get; set; }
            public decimal CutYardage { get; set; }
            public decimal RemnantYardage { get; set; }
            public string SourceSerial { get; set; }
            public bool SuggestFullRoll { get; set; }
            public string AdjustmentRefNbr { get; set; }
            public string ErrorMessage { get; set; }
        }

        /// <summary>Result of a cut validation check (no side effects).</summary>
        public class CutValidation
        {
            public bool IsValid { get; set; }
            public bool SuggestFullRoll { get; set; }
            public decimal AvailableYardage { get; set; }
            public decimal RemnantYardage { get; set; }
            public string ErrorMessage { get; set; }
        }

        #endregion
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using PX.Data;
using PX.Data.BQL;
using PX.Data.BQL.Fluent;
using PX.Objects.CS;
using PX.Objects.IN;
using PX.Objects.PO;

namespace Aesthetik.WMS
{
    /// <summary>
    /// Pre-receiving engine for advance allocation of piece goods inventory.
    ///
    /// Creates serial numbers, lot attributes, and bin assignments from PO/ASN data
    /// BEFORE goods physically arrive at the warehouse. This enables:
    ///   - Selling specific rolls from in-transit containers
    ///   - Planned put-away (warehouse knows which bin each roll goes to)
    ///   - Cross-dock fulfillment upon container arrival
    ///
    /// Supports two ingest methods:
    ///   1. EDI 856 ASN (via SPS Commerce) — automated, preferred for high-volume mills
    ///   2. Manual CSV upload — for mills without EDI capability
    ///
    /// Target: Acumatica 2024 R2
    /// </summary>
    public class PreReceivingEngine
    {
        private readonly PXGraph _graph;

        public PreReceivingEngine(PXGraph graph)
        {
            _graph = graph ?? throw new ArgumentNullException(nameof(graph));
        }

        #region CSV Import

        /// <summary>
        /// Imports a packing list CSV and creates pre-receiving serial records.
        ///
        /// Required columns: PO Number, SKU, Yardage, Dye Lot
        /// Optional columns: Width, Shade Code, Container Number
        /// </summary>
        public PreReceivingResult ImportPackingListCSV(Stream csvStream, int warehouseID)
        {
            var result = new PreReceivingResult();
            var lines = new List<PackingListLine>();

            // ── STEP 1: Parse CSV ──────────────────────────────────────────
            try
            {
                using (var reader = new StreamReader(csvStream))
                {
                    string headerLine = reader.ReadLine();
                    if (string.IsNullOrWhiteSpace(headerLine))
                    {
                        result.Errors.Add("CSV file is empty or missing header row.");
                        return result;
                    }

                    var headers = ParseCSVRow(headerLine);
                    var columnMap = BuildColumnMap(headers);

                    if (!ValidateRequiredColumns(columnMap, result))
                        return result;

                    int rowNumber = 1;
                    string line;
                    while ((line = reader.ReadLine()) != null)
                    {
                        rowNumber++;
                        if (string.IsNullOrWhiteSpace(line)) continue;

                        var parsed = ParsePackingListRow(ParseCSVRow(line), columnMap, rowNumber);
                        if (parsed.Errors.Count > 0)
                            result.Warnings.AddRange(parsed.Errors);
                        else
                            lines.Add(parsed.Line);
                    }
                }
            }
            catch (Exception ex)
            {
                result.Errors.Add($"CSV parse error: {ex.Message}");
                return result;
            }

            if (lines.Count == 0)
            {
                result.Errors.Add("No valid lines found in CSV.");
                return result;
            }

            // ── STEP 2: Validate against Acumatica ────────────────────────
            var validLines = ValidateAgainstERP(lines, result);

            // ── STEP 3: Create serial numbers ──────────────────────────────
            var createdSerials = CreatePreReceivingSerials(validLines, warehouseID, result);

            // ── STEP 4: Assign bins ────────────────────────────────────────
            if (createdSerials.Count > 0)
            {
                AssignBins(createdSerials, warehouseID);
                result.BinsAssigned = createdSerials.Count;
            }

            result.Success = result.Errors.Count == 0;
            return result;
        }

        /// <summary>
        /// Parses a single CSV row respecting quoted fields with commas.
        /// </summary>
        private string[] ParseCSVRow(string line)
        {
            var fields = new List<string>();
            bool inQuotes = false;
            var current = new System.Text.StringBuilder();

            foreach (char c in line)
            {
                if (c == '"')
                {
                    inQuotes = !inQuotes;
                }
                else if (c == ',' && !inQuotes)
                {
                    fields.Add(current.ToString().Trim());
                    current.Clear();
                }
                else
                {
                    current.Append(c);
                }
            }
            fields.Add(current.ToString().Trim());

            return fields.ToArray();
        }

        /// <summary>
        /// Builds a case-insensitive column name → index map from CSV headers.
        /// </summary>
        private Dictionary<string, int> BuildColumnMap(string[] headers)
        {
            var map = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < headers.Length; i++)
            {
                string normalized = headers[i].Trim().Replace(" ", "").Replace("_", "");
                map[normalized] = i;

                // Also store the original for case-insensitive lookup
                map[headers[i].Trim()] = i;
            }
            return map;
        }

        /// <summary>
        /// Validates that all required columns are present in the CSV.
        /// </summary>
        private bool ValidateRequiredColumns(Dictionary<string, int> columnMap, PreReceivingResult result)
        {
            var required = new[] { "PONumber", "SKU", "Yardage", "DyeLot" };
            var alternates = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)
            {
                { "PONumber", new[] { "PO Number", "PO", "PONbr", "PO_Number", "PONumber" } },
                { "SKU", new[] { "SKU", "ItemID", "Item", "InventoryID", "Item ID" } },
                { "Yardage", new[] { "Yardage", "Yards", "Qty", "Quantity", "ActualYardage" } },
                { "DyeLot", new[] { "DyeLot", "Dye Lot", "DyeLotNumber", "Lot", "LotNumber" } },
            };

            bool allFound = true;
            foreach (string req in required)
            {
                bool found = false;
                if (alternates.TryGetValue(req, out var alts))
                {
                    foreach (string alt in alts)
                    {
                        string normalized = alt.Replace(" ", "").Replace("_", "");
                        if (columnMap.ContainsKey(normalized) || columnMap.ContainsKey(alt))
                        {
                            found = true;
                            break;
                        }
                    }
                }

                if (!found)
                {
                    result.Errors.Add($"Required column '{req}' not found. Expected one of: {string.Join(", ", alternates[req])}");
                    allFound = false;
                }
            }

            return allFound;
        }

        /// <summary>
        /// Parses a single packing list row from CSV field values.
        /// </summary>
        private (PackingListLine Line, List<string> Errors) ParsePackingListRow(
            string[] fields, Dictionary<string, int> columnMap, int rowNumber)
        {
            var errors = new List<string>();
            var line = new PackingListLine();

            line.PONumber = GetField(fields, columnMap,
                "PONumber", "PO Number", "PO", "PONbr");
            line.SKU = GetField(fields, columnMap,
                "SKU", "ItemID", "Item", "InventoryID");

            string yardageStr = GetField(fields, columnMap,
                "Yardage", "Yards", "Qty", "Quantity");
            string dyeLot = GetField(fields, columnMap,
                "DyeLot", "Dye Lot", "Lot", "LotNumber");

            // Validate required fields
            if (string.IsNullOrEmpty(line.PONumber))
                errors.Add($"Row {rowNumber}: Missing PO Number");
            if (string.IsNullOrEmpty(line.SKU))
                errors.Add($"Row {rowNumber}: Missing SKU");
            if (string.IsNullOrEmpty(dyeLot))
                errors.Add($"Row {rowNumber}: Missing Dye Lot");

            if (decimal.TryParse(yardageStr, NumberStyles.Any, CultureInfo.InvariantCulture, out decimal yardage))
            {
                if (yardage <= 0)
                    errors.Add($"Row {rowNumber}: Yardage must be positive (got {yardage})");
                else
                    line.Yardage = yardage;
            }
            else
            {
                errors.Add($"Row {rowNumber}: Invalid yardage value '{yardageStr}'");
            }

            line.DyeLot = dyeLot;

            // Optional fields
            string widthStr = GetField(fields, columnMap, "Width", "WidthInches", "Width (inches)");
            if (!string.IsNullOrEmpty(widthStr) &&
                decimal.TryParse(widthStr, NumberStyles.Any, CultureInfo.InvariantCulture, out decimal width))
            {
                line.Width = width;
            }

            line.ShadeCode = GetField(fields, columnMap, "ShadeCode", "Shade Code", "Shade");
            line.ContainerNumber = GetField(fields, columnMap, "ContainerNumber", "Container Number", "Container", "Container #");

            return (line, errors);
        }

        /// <summary>
        /// Gets a field value by trying multiple column name variants.
        /// </summary>
        private string GetField(string[] fields, Dictionary<string, int> columnMap, params string[] nameVariants)
        {
            foreach (string name in nameVariants)
            {
                string normalized = name.Replace(" ", "").Replace("_", "");
                int idx = -1;

                if (columnMap.TryGetValue(normalized, out idx) || columnMap.TryGetValue(name, out idx))
                {
                    if (idx >= 0 && idx < fields.Length)
                    {
                        string value = fields[idx].Trim();
                        if (!string.IsNullOrEmpty(value))
                            return value;
                    }
                }
            }
            return null;
        }

        #endregion

        #region EDI 856 ASN Import

        /// <summary>
        /// Processes an EDI 856 Advanced Shipping Notice from SPS Commerce.
        /// Creates pre-receiving serial records from ASN roll-level detail.
        /// </summary>
        public PreReceivingResult ImportEDI856(ASNData asnData, int warehouseID)
        {
            var result = new PreReceivingResult();

            if (asnData?.Lines == null || asnData.Lines.Count == 0)
            {
                result.Errors.Add("ASN contains no line items.");
                return result;
            }

            // EDI 856 provides the same data as CSV but from automated source.
            // Apply the container number from the ASN header to all lines if not set per-line.
            foreach (var line in asnData.Lines)
            {
                if (string.IsNullOrEmpty(line.ContainerNumber))
                    line.ContainerNumber = asnData.ContainerNumber;
            }

            // Validate and create serials using the same pipeline as CSV
            var validLines = ValidateAgainstERP(asnData.Lines, result);
            var createdSerials = CreatePreReceivingSerials(validLines, warehouseID, result);

            if (createdSerials.Count > 0)
            {
                AssignBins(createdSerials, warehouseID);
                result.BinsAssigned = createdSerials.Count;
            }

            result.Success = result.Errors.Count == 0;
            return result;
        }

        #endregion

        #region ERP Validation

        /// <summary>
        /// Validates packing list lines against Acumatica data:
        ///   - PO exists and is open/approved
        ///   - SKU exists and uses PIECEGOODS lot/serial class
        ///   - No duplicate serial would be created
        /// </summary>
        private List<PackingListLine> ValidateAgainstERP(
            List<PackingListLine> lines, PreReceivingResult result)
        {
            var valid = new List<PackingListLine>();

            // Cache PO and SKU lookups to avoid repeated queries
            var poCache = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase);
            var skuCache = new Dictionary<string, (int? InventoryID, bool IsPieceGoods)>(
                StringComparer.OrdinalIgnoreCase);

            foreach (var line in lines)
            {
                bool lineValid = true;

                // Validate PO
                if (!poCache.TryGetValue(line.PONumber, out bool poValid))
                {
                    var po = SelectFrom<POOrder>
                        .Where<POOrder.orderNbr.IsEqual<@P.AsString>>
                        .View.ReadOnly.Select(_graph, line.PONumber);

                    poValid = po != null;
                    poCache[line.PONumber] = poValid;
                }

                if (!poValid)
                {
                    result.Warnings.Add($"PO '{line.PONumber}' not found in Acumatica. Line skipped.");
                    lineValid = false;
                }

                // Validate SKU and check lot/serial class
                if (!skuCache.TryGetValue(line.SKU, out var skuInfo))
                {
                    var item = SelectFrom<InventoryItem>
                        .Where<InventoryItem.inventoryCD.IsEqual<@P.AsString>>
                        .View.ReadOnly.Select(_graph, line.SKU);

                    if (item != null)
                    {
                        var inv = (InventoryItem)item;
                        bool isPG = string.Equals(inv.LotSerClassID,
                            PieceGoodsConstants.LotSerialClassID,
                            StringComparison.OrdinalIgnoreCase);
                        skuInfo = (inv.InventoryID, isPG);
                    }
                    else
                    {
                        skuInfo = (null, false);
                    }
                    skuCache[line.SKU] = skuInfo;
                }

                if (!skuInfo.InventoryID.HasValue)
                {
                    result.Warnings.Add($"SKU '{line.SKU}' not found in Acumatica. Line skipped.");
                    lineValid = false;
                }
                else if (!skuInfo.IsPieceGoods)
                {
                    result.Warnings.Add(
                        $"SKU '{line.SKU}' is not assigned to the '{PieceGoodsConstants.LotSerialClassID}' " +
                        $"lot/serial class. Line skipped.");
                    lineValid = false;
                }

                if (lineValid)
                    valid.Add(line);
            }

            return valid;
        }

        #endregion

        #region Serial Creation

        /// <summary>
        /// Creates pre-receiving serial records for validated packing list lines.
        /// Each line becomes one serial in INLotSerialStatus with status = In-Transit.
        /// </summary>
        private List<CreatedSerial> CreatePreReceivingSerials(
            List<PackingListLine> lines, int warehouseID, PreReceivingResult result)
        {
            var created = new List<CreatedSerial>();

            // Load INSetup for defaults
            var setup = SelectFrom<INSetup>.View.ReadOnly.SelectSingleBound(_graph, null);
            var setupExt = ((INSetup)setup)?.GetExtension<INSetupExt>();

            // Group by SKU for sequential serial numbering per SKU per day
            var grouped = lines.GroupBy(l => l.SKU, StringComparer.OrdinalIgnoreCase);
            var today = DateTime.Today;

            foreach (var skuGroup in grouped)
            {
                string sku = skuGroup.Key;

                // Look up inventory ID (already validated)
                var item = SelectFrom<InventoryItem>
                    .Where<InventoryItem.inventoryCD.IsEqual<@P.AsString>>
                    .View.ReadOnly.Select(_graph, sku);
                int inventoryID = ((InventoryItem)item).InventoryID.Value;

                // Determine next sequence number for this SKU today
                int seq = GetNextSerialSequence(sku, today);

                decimal defaultWidth = 54.0m;

                foreach (var line in skuGroup)
                {
                    try
                    {
                        // Generate serial number: [SKU]-[YYMMDD]-[SEQ]
                        string serialNbr = string.Format(
                            PieceGoodsConstants.SerialFormat, sku, today, seq++);

                        // Create the INLotSerialStatus record via the graph's cache
                        var statusCache = _graph.Caches[typeof(INLotSerialStatus)];
                        var status = (INLotSerialStatus)statusCache.CreateInstance();
                        status.InventoryID = inventoryID;
                        status.SiteID = warehouseID;
                        status.LotSerialNbr = serialNbr;
                        status = (INLotSerialStatus)statusCache.Insert(status);

                        // Set extension fields
                        var ext = status.GetExtension<INLotSerialStatusExt>();
                        ext.UsrActualYardage = line.Yardage;
                        ext.UsrDyeLot = line.DyeLot;
                        ext.UsrWidth = line.Width ?? defaultWidth;
                        ext.UsrShadeCode = line.ShadeCode;
                        ext.UsrContainerNo = line.ContainerNumber;
                        ext.UsrInventoryStatus = PieceGoodsConstants.InvStatus_InTransit;
                        ext.UsrSourceRoll = null;  // Original roll, not a cut piece
                        ext.UsrDefectFlag = false;

                        statusCache.Update(status);

                        created.Add(new CreatedSerial
                        {
                            SerialNbr = serialNbr,
                            InventoryID = inventoryID,
                            SKU = sku,
                            Yardage = line.Yardage,
                            DyeLot = line.DyeLot,
                            ContainerNumber = line.ContainerNumber,
                        });

                        result.CreatedSerials.Add(serialNbr);
                        result.SerialsCreated++;
                    }
                    catch (Exception ex)
                    {
                        result.Warnings.Add(
                            $"Failed to create serial for SKU '{sku}', " +
                            $"PO '{line.PONumber}': {ex.Message}");
                    }
                }
            }

            // Persist all created records
            if (created.Count > 0)
            {
                _graph.Actions.PressSave();
            }

            return created;
        }

        /// <summary>
        /// Determines the next available sequence number for a SKU on a given date.
        /// Queries existing serials matching the pattern [SKU]-[YYMMDD]-*.
        /// </summary>
        private int GetNextSerialSequence(string sku, DateTime date)
        {
            string prefix = $"{sku}-{date:yyMMdd}-";

            var existing = SelectFrom<INLotSerialStatus>
                .Where<INLotSerialStatus.lotSerialNbr.IsLike<@P.AsString>>
                .View.ReadOnly.Select(_graph, prefix + "%");

            int maxSeq = 0;
            foreach (PXResult<INLotSerialStatus> row in existing)
            {
                var status = (INLotSerialStatus)row;
                string nbr = status.LotSerialNbr;
                if (nbr.StartsWith(prefix) && nbr.Length > prefix.Length)
                {
                    string seqStr = nbr.Substring(prefix.Length);
                    if (int.TryParse(seqStr, out int seq) && seq > maxSeq)
                        maxSeq = seq;
                }
            }

            return maxSeq + 1;
        }

        #endregion

        #region Bin Pre-Assignment

        /// <summary>
        /// Assigns target bin locations to pre-received serials based on:
        ///   - SKU zone affinity (item class → warehouse zone mapping)
        ///   - Velocity-based slotting (fast movers near dock)
        ///   - Capacity verification (bin can physically hold the roll)
        ///   - Dye lot grouping (same lot → adjacent bins when possible)
        /// </summary>
        public void AssignBins(List<CreatedSerial> serials, int warehouseID)
        {
            if (serials == null || serials.Count == 0) return;

            // Load all available bin locations for the warehouse
            var locations = SelectFrom<INLocation>
                .Where<INLocation.siteID.IsEqual<@P.AsInt>
                    .And<INLocation.active.IsEqual<True>>>
                .View.ReadOnly.Select(_graph, warehouseID)
                .Select(r => (INLocation)r)
                .ToList();

            // Exclude virtual locations (RECV-DOCK, staging)
            var binLocations = locations
                .Where(l => !l.LocationCD.StartsWith("RECV", StringComparison.OrdinalIgnoreCase))
                .OrderBy(l => l.LocationCD)
                .ToList();

            if (binLocations.Count == 0) return;

            // Track which bins have been assigned in this batch to avoid over-filling
            var binAssignmentCounts = new Dictionary<int, int>();

            // Group serials by dye lot for grouping assignment
            var dyeLotGroups = serials
                .GroupBy(s => s.DyeLot ?? "", StringComparer.OrdinalIgnoreCase)
                .ToList();

            int binIndex = 0;
            foreach (var lotGroup in dyeLotGroups)
            {
                // Assign all rolls from the same dye lot to adjacent bins
                foreach (var serial in lotGroup)
                {
                    if (binIndex >= binLocations.Count)
                        binIndex = 0; // Wrap around if more rolls than bins

                    var targetBin = binLocations[binIndex];

                    // Update the serial's pre-assigned bin
                    var statusRecord = SelectFrom<INLotSerialStatus>
                        .Where<INLotSerialStatus.inventoryID.IsEqual<@P.AsInt>
                            .And<INLotSerialStatus.lotSerialNbr.IsEqual<@P.AsString>>>
                        .View.Select(_graph, serial.InventoryID, serial.SerialNbr);

                    if (statusRecord != null)
                    {
                        var status = (INLotSerialStatus)statusRecord;
                        var ext = status.GetExtension<INLotSerialStatusExt>();
                        ext.UsrPreAssignedBin = targetBin.LocationCD;

                        _graph.Caches[typeof(INLotSerialStatus)].Update(status);
                    }

                    // Track assignment count per bin
                    int locID = targetBin.LocationID.Value;
                    binAssignmentCounts.TryGetValue(locID, out int count);
                    binAssignmentCounts[locID] = count + 1;

                    // Move to next bin after each roll (or stay for dye lot grouping)
                    // For dye lot grouping: only advance bin after the group is done
                }

                // Advance bin index after each dye lot group to keep lots together
                binIndex++;
            }

            _graph.Actions.PressSave();
        }

        /// <summary>
        /// Overload for assigning bins using serial number strings only.
        /// Resolves each serial to its inventory ID before assignment.
        /// </summary>
        public void AssignBins(List<string> serialNbrs, int warehouseID)
        {
            var serials = new List<CreatedSerial>();
            foreach (string nbr in serialNbrs)
            {
                var status = SelectFrom<INLotSerialStatus>
                    .Where<INLotSerialStatus.lotSerialNbr.IsEqual<@P.AsString>>
                    .View.ReadOnly.Select(_graph, nbr);

                if (status != null)
                {
                    var s = (INLotSerialStatus)status;
                    var ext = s.GetExtension<INLotSerialStatusExt>();
                    serials.Add(new CreatedSerial
                    {
                        SerialNbr = nbr,
                        InventoryID = s.InventoryID.Value,
                        DyeLot = ext?.UsrDyeLot,
                    });
                }
            }

            AssignBins(serials, warehouseID);
        }

        #endregion

        #region Supporting Types

        /// <summary>A single line from a mill packing list (CSV or EDI source).</summary>
        public class PackingListLine
        {
            public string PONumber { get; set; }
            public string SKU { get; set; }
            public decimal Yardage { get; set; }
            public string DyeLot { get; set; }
            public decimal? Width { get; set; }
            public string ShadeCode { get; set; }
            public string ContainerNumber { get; set; }
        }

        /// <summary>Parsed EDI 856 ASN data (from SPS Commerce).</summary>
        public class ASNData
        {
            public string ShipmentID { get; set; }
            public DateTime ShipDate { get; set; }
            public string ContainerNumber { get; set; }
            public List<PackingListLine> Lines { get; set; } = new List<PackingListLine>();
        }

        /// <summary>Result of a pre-receiving import operation.</summary>
        public class PreReceivingResult
        {
            public bool Success { get; set; }
            public int SerialsCreated { get; set; }
            public int BinsAssigned { get; set; }
            public List<string> CreatedSerials { get; set; } = new List<string>();
            public List<string> Errors { get; set; } = new List<string>();
            public List<string> Warnings { get; set; } = new List<string>();
        }

        /// <summary>Internal tracking for a serial created during pre-receiving.</summary>
        public class CreatedSerial
        {
            public string SerialNbr { get; set; }
            public int InventoryID { get; set; }
            public string SKU { get; set; }
            public decimal Yardage { get; set; }
            public string DyeLot { get; set; }
            public string ContainerNumber { get; set; }
        }

        #endregion
    }
}

using System;

namespace Aesthetik.WMS
{
    /// <summary>
    /// Constants used throughout the Piece Goods WMS customization.
    /// All magic strings, attribute IDs, and default values are centralized here.
    /// </summary>
    public static class PieceGoodsConstants
    {
        #region Lot/Serial Class

        /// <summary>Lot/serial class ID for all piece goods items.</summary>
        public const string LotSerialClassID = "PIECEGOODS";

        /// <summary>Serial number format: [SKU]-[YYMMDD]-[SEQ]</summary>
        public const string SerialFormat = "{0}-{1:yyMMdd}-{2:D3}";

        /// <summary>Cut piece serial suffix format: -C[SEQ]</summary>
        public const string DefaultCutSerialSuffix = "-C{0}";

        #endregion

        #region Lot/Serial Attributes

        public const string Attr_ActualYardage   = "ACTYARDAGE";
        public const string Attr_DyeLot          = "DYELOT";
        public const string Attr_Width            = "WIDTHIN";
        public const string Attr_ShadeCode        = "SHADECODE";
        public const string Attr_SourceRoll       = "SOURCEROLL";
        public const string Attr_DefectFlag       = "DEFECTFLAG";
        public const string Attr_InventoryStatus  = "INVSTATUS";
        public const string Attr_PreAssignedBin   = "PREASSIGNBIN";
        public const string Attr_ContainerNumber  = "CONTAINERNO";

        #endregion

        #region Inventory Status Values

        public const string InvStatus_InTransit    = "IN-TRANSIT";
        public const string InvStatus_Receiving    = "RECEIVING";
        public const string InvStatus_PutAway      = "PUT-AWAY";
        public const string InvStatus_Available    = "AVAILABLE";
        public const string InvStatus_CrossDockHold = "XDOCK-HOLD";

        #endregion

        #region Warehouse Locations

        /// <summary>Virtual receiving dock location for cross-dock workflow.</summary>
        public const string Location_RecvDock = "RECV-DOCK";

        /// <summary>Staging sub-location prefix for large warehouses.</summary>
        public const string Location_StagingPrefix = "RECV-STAGING-";

        /// <summary>Number of default staging sub-locations.</summary>
        public const int DefaultStagingLocations = 4;

        #endregion

        #region GS1-128 Application Identifiers

        /// <summary>AI 01: GTIN / SKU</summary>
        public const string AI_GTIN = "01";

        /// <summary>AI 21: Serial Number</summary>
        public const string AI_Serial = "21";

        /// <summary>AI 10: Batch/Lot Number (Dye Lot)</summary>
        public const string AI_Lot = "10";

        /// <summary>GS1 FNC1 separator character.</summary>
        public const char GS1_FNC1 = '\u001D';

        /// <summary>GS1 AI start parenthesis (human-readable format).</summary>
        public const char GS1_AI_Start = '(';
        public const char GS1_AI_End = ')';

        #endregion

        #region Configuration Defaults

        public const decimal DefaultMinRemnantYardage       = 1.0m;
        public const bool    DefaultAutoQuantityMode        = true;
        public const int     DefaultDyeLotMatchWeight       = 15;
        public const bool    DefaultAutoPrintLabel          = true;
        public const bool    DefaultPreReceivingEnabled     = true;
        public const bool    DefaultCrossDockEnabled        = true;
        public const int     DefaultCrossDockAgeDays        = 5;
        public const int     DefaultInTransitAllocWeight    = -20;
        public const decimal DefaultYardageVarianceThreshold = 0.02m;

        // Pick optimizer scoring weights
        public const int DefaultWeight_ExactMatch       = 50;
        public const int DefaultWeight_MinimizeRemnant  = 30;
        public const int DefaultWeight_DyeLotMatch      = 15;
        public const int DefaultWeight_LocationPref     = 10;
        public const int DefaultWeight_FIFOAge          = 5;

        #endregion

        #region Scan Commands

        /// <summary>Scan command to enter pick mode.</summary>
        public const string ScanCmd_Pick    = "@pick";

        /// <summary>Scan command to confirm an action (e.g., cut confirmation).</summary>
        public const string ScanCmd_Confirm = "@confirm";

        /// <summary>Scan command to override a suggestion.</summary>
        public const string ScanCmd_Override = "@override";

        /// <summary>Scan command to skip a pick line.</summary>
        public const string ScanCmd_Skip = "@skip";

        /// <summary>Scan command to print label.</summary>
        public const string ScanCmd_Print = "@print";

        #endregion

        #region Custom Field Names (DAC extensions)

        // INLotSerialStatus extension fields
        public const string Fld_ActualYardage        = "UsrActualYardage";
        public const string Fld_DyeLot               = "UsrDyeLot";
        public const string Fld_Width                = "UsrWidth";
        public const string Fld_ShadeCode            = "UsrShadeCode";
        public const string Fld_SourceRoll           = "UsrSourceRoll";
        public const string Fld_DefectFlag           = "UsrDefectFlag";
        public const string Fld_InventoryStatus      = "UsrInventoryStatus";
        public const string Fld_PreAssignedBin       = "UsrPreAssignedBin";
        public const string Fld_ContainerNumber      = "UsrContainerNo";

        // INSetup extension fields
        public const string Fld_PGMinRemnant         = "UsrPGMinRemnant";
        public const string Fld_PGAutoQtyMode        = "UsrPGAutoQtyMode";
        public const string Fld_PGDyeLotWeight       = "UsrPGDyeLotWeight";
        public const string Fld_PGAutoPrint          = "UsrPGAutoPrint";
        public const string Fld_PGCutSerialSuffix    = "UsrPGCutSuffix";
        public const string Fld_PGPreReceiving       = "UsrPGPreRecv";
        public const string Fld_PGCrossDock          = "UsrPGCrossDock";
        public const string Fld_PGCrossDockAgeDays   = "UsrPGXDockAge";
        public const string Fld_PGInTransitWeight    = "UsrPGInTransitWt";
        public const string Fld_PGYardageVariance    = "UsrPGYardageVar";

        // Pick optimizer weight fields on INSetup
        public const string Fld_PGWtExactMatch       = "UsrPGWtExact";
        public const string Fld_PGWtMinRemnant       = "UsrPGWtRemnant";
        public const string Fld_PGWtDyeLot           = "UsrPGWtDyeLot";
        public const string Fld_PGWtLocation         = "UsrPGWtLocation";
        public const string Fld_PGWtFIFO             = "UsrPGWtFIFO";

        #endregion
    }
}

using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

namespace Aesthetik.WMS
{
    /// <summary>
    /// Parser for GS1-128 compound barcodes used on piece goods roll labels.
    ///
    /// Decodes Application Identifiers (AIs) from the barcode data:
    ///   AI 01 (GTIN/SKU): Item inventory ID
    ///   AI 21 (Serial):   Unique roll serial number
    ///   AI 10 (Lot):      Dye lot identifier
    ///
    /// Supports two input formats:
    ///   1. FNC1-delimited (scanner output): data fields separated by GS character (0x1D)
    ///   2. Human-readable (parenthesized): (01)FAB-1024(21)260301-001(10)DL-2026-0412
    ///
    /// Keyence scanners are pre-configured to parse GS1-128 AIs natively and output
    /// decoded fields. This parser handles both raw and Keyence-decoded formats.
    /// </summary>
    public static class BarcodeParser
    {
        /// <summary>
        /// Attempts to parse a GS1-128 compound barcode string.
        /// Returns true if at least one AI was successfully decoded.
        /// </summary>
        /// <param name="barcodeData">Raw barcode data from scanner.</param>
        /// <param name="result">Parsed barcode fields.</param>
        /// <returns>True if parsing succeeded.</returns>
        public static bool TryParseGS1128(string barcodeData, out GS1128Result result)
        {
            result = new GS1128Result();

            if (string.IsNullOrWhiteSpace(barcodeData))
                return false;

            // Determine format and parse
            Dictionary<string, string> ais;

            if (barcodeData.Contains(PieceGoodsConstants.GS1_AI_Start.ToString()))
            {
                // Human-readable format: (01)FAB-1024(21)260301-001(10)DL-2026-0412
                ais = ParseHumanReadable(barcodeData);
            }
            else if (barcodeData.Contains(PieceGoodsConstants.GS1_FNC1.ToString()))
            {
                // FNC1-delimited format from scanner
                ais = ParseFNC1Delimited(barcodeData);
            }
            else
            {
                // Attempt to match as a simple serial number (no AI encoding)
                // This handles cases where the Keyence scanner pre-strips AIs
                result.RawSerial = barcodeData.Trim();
                return true;
            }

            if (ais == null || ais.Count == 0)
            {
                // Fallback: treat entire string as a serial
                result.RawSerial = barcodeData.Trim();
                return true;
            }

            // Map AIs to result fields
            if (ais.TryGetValue(PieceGoodsConstants.AI_GTIN, out var gtin))
                result.SKU = gtin;

            if (ais.TryGetValue(PieceGoodsConstants.AI_Serial, out var serial))
                result.SerialNumber = serial;

            if (ais.TryGetValue(PieceGoodsConstants.AI_Lot, out var lot))
                result.DyeLot = lot;

            result.HasSKU    = !string.IsNullOrEmpty(result.SKU);
            result.HasSerial = !string.IsNullOrEmpty(result.SerialNumber);
            result.HasDyeLot = !string.IsNullOrEmpty(result.DyeLot);

            return result.HasSKU || result.HasSerial;
        }

        /// <summary>
        /// Parses human-readable GS1-128 format: (AI)value(AI)value...
        /// </summary>
        private static Dictionary<string, string> ParseHumanReadable(string data)
        {
            var result = new Dictionary<string, string>(StringComparer.Ordinal);

            // Regex: capture (nn) followed by value until next ( or end
            var matches = Regex.Matches(data, @"\((\d{2,4})\)([^(]*)");

            foreach (Match match in matches)
            {
                if (match.Groups.Count >= 3)
                {
                    string ai = match.Groups[1].Value;
                    string value = match.Groups[2].Value.TrimEnd();
                    result[ai] = value;
                }
            }

            return result;
        }

        /// <summary>
        /// Parses FNC1-delimited GS1-128 format from scanner output.
        /// Fields are separated by GS (Group Separator, 0x1D) character.
        /// Each field starts with a 2-4 digit AI prefix.
        /// </summary>
        private static Dictionary<string, string> ParseFNC1Delimited(string data)
        {
            var result = new Dictionary<string, string>(StringComparer.Ordinal);

            // Split on FNC1 separator
            string[] segments = data.Split(PieceGoodsConstants.GS1_FNC1);

            foreach (string segment in segments)
            {
                if (string.IsNullOrWhiteSpace(segment)) continue;

                // Known fixed-length AIs
                // AI 01 (GTIN): 14 digits fixed (but we use variable-length SKUs)
                // AI 10 (Lot): variable length
                // AI 21 (Serial): variable length

                // Try 2-digit AI prefix first
                if (segment.Length >= 3)
                {
                    string ai2 = segment.Substring(0, 2);
                    if (IsKnownAI(ai2))
                    {
                        result[ai2] = segment.Substring(2);
                        continue;
                    }
                }

                // Try 4-digit AI prefix (less common for our use case)
                if (segment.Length >= 5)
                {
                    string ai4 = segment.Substring(0, 4);
                    if (IsKnownAI(ai4))
                    {
                        result[ai4] = segment.Substring(4);
                        continue;
                    }
                }
            }

            return result;
        }

        /// <summary>
        /// Checks if the given string is a known GS1 Application Identifier.
        /// </summary>
        private static bool IsKnownAI(string ai)
        {
            return ai == PieceGoodsConstants.AI_GTIN   // 01
                || ai == PieceGoodsConstants.AI_Serial  // 21
                || ai == PieceGoodsConstants.AI_Lot;    // 10
        }

        /// <summary>
        /// Generates a GS1-128 human-readable barcode string for label printing.
        /// </summary>
        /// <param name="sku">Item inventory ID.</param>
        /// <param name="serialNumber">Roll serial number.</param>
        /// <param name="dyeLot">Dye lot identifier (optional).</param>
        /// <returns>Formatted barcode string: (01)SKU(21)Serial(10)Lot</returns>
        public static string GenerateGS1128Label(string sku, string serialNumber, string dyeLot = null)
        {
            var label = $"(01){sku}(21){serialNumber}";

            if (!string.IsNullOrEmpty(dyeLot))
                label += $"(10){dyeLot}";

            return label;
        }

        /// <summary>
        /// Generates FNC1-delimited barcode data for Keyence printer input.
        /// </summary>
        public static string GenerateGS1128Raw(string sku, string serialNumber, string dyeLot = null)
        {
            var fnc1 = PieceGoodsConstants.GS1_FNC1;
            var data = $"01{sku}{fnc1}21{serialNumber}";

            if (!string.IsNullOrEmpty(dyeLot))
                data += $"{fnc1}10{dyeLot}";

            return data;
        }
    }

    /// <summary>
    /// Result of parsing a GS1-128 compound barcode.
    /// </summary>
    public class GS1128Result
    {
        /// <summary>Item inventory ID (from AI 01).</summary>
        public string SKU { get; set; }

        /// <summary>Roll serial number (from AI 21).</summary>
        public string SerialNumber { get; set; }

        /// <summary>Dye lot identifier (from AI 10).</summary>
        public string DyeLot { get; set; }

        /// <summary>Raw serial string if no AI encoding was detected.</summary>
        public string RawSerial { get; set; }

        public bool HasSKU { get; set; }
        public bool HasSerial { get; set; }
        public bool HasDyeLot { get; set; }

        /// <summary>
        /// Returns the most useful serial identifier:
        /// AI-decoded serial if available, otherwise the raw string.
        /// </summary>
        public string EffectiveSerial => SerialNumber ?? RawSerial;
    }
}

